                        sku: product.id,
                        name: { en: product.name },
                        description: { en: product.description },
                        shortDescription: { en: product.description },
                        type: mapCoffeeTypeToCatalog(product.coffeeType),
                        grade: mapGradeToCatalog(product.grade),
