                              imageObj.caption = { en: img.caption };
                            }
                            return imageObj;
                          }) || [],
                        documents: [],
                        packagingOptions: [],
                        isActive: true,
                        isFeatured: product.isFeatured || false,
                        sortOrder: 0,
                        createdAt: new Date(),
                        updatedAt: new Date(),
                        createdBy: 'system',
                        updatedBy: 'system',
