                          Description
                        </TabsTrigger>
                        <TabsTrigger
                          value="specifications"
                          className="data-[state=active]:bg-gold-500 data-[state=active]:text-white"
                        >
                          Specifications
                        </TabsTrigger>
                        <TabsTrigger
                          value="availability"
                          className="data-[state=active]:bg-gold-500 data-[state=active]:text-white"
                        >
                          Availability
                        </TabsTrigger>
                        <TabsTrigger
                          value="origin"
                          className="data-[state=active]:bg-gold-500 data-[state=active]:text-white"
                        >
                          Origin
                        </TabsTrigger>
                        <TabsTrigger
                          value="quality"
