                          className="data-[state=active]:bg-gold-500 data-[state=active]:text-white"
                        >
                          Documents
                        </TabsTrigger>
                      </TabsList>

                      <TabsContent value="description" className="mt-6">
                        <Card className="shadow-md">
                          <CardContent className="p-6">
                            <SectionHeading
                              size="lg"
                              className="mb-4 text-coffee-800"
                            >
                              Product Description
