          //     supplier: {
          //       select: {
          //         id: true,
          //         name: true,
          //         country: true,
          //       },
          //     },
          //   },
          // },
          pricingModels: {
            where: { isActive: true },
            take: 1,
            include: {
              pricingModel: true,
            },
          },
          // inventory: {
          //   take: 1,
          //   orderBy: { lastUpdated: 'desc' },
          // },
        },
        orderBy,
        skip,
        take: limit,
      }),
      prisma.coffeeProduct.count({ where }),
    ]);

    // Calculate pagination info
    const totalPages = Math.ceil(totalCount / limit);
    const hasNextPage = page < totalPages;
    const hasPrevPage = page > 1;

    // Get aggregated filter data for faceted search
    const [
      coffeeTypes,
      grades,
      processingMethods,
      origins,
      regions,
      availableCertifications,
    ] = await Promise.all([
      prisma.coffeeProduct.groupBy({
        by: ['coffeeType'],
        where: { isActive: true },
        _count: true,
      }),
      prisma.coffeeProduct.groupBy({
        by: ['grade'],
        where: { isActive: true },
        _count: true,
      }),
      prisma.coffeeProduct.groupBy({
        by: ['processing'],
        where: { isActive: true },
        _count: true,
      }),
      prisma.coffeeProduct.groupBy({
        by: ['origin'],
        where: { isActive: true },
        _count: true,
      }),
      prisma.coffeeProduct.groupBy({
        by: ['region'],
        where: { isActive: true, region: { not: null } },
        _count: true,
      }),
      prisma.certification.findMany({
        where: {
          isActive: true,
          products: {
            some: {
              product: {
                isActive: true,
              },
            },
          },
        },
        include: {
          translations: {
            where: { locale },
          },
          _count: {
            select: {
              products: {
                where: {
                  product: {
                    isActive: true,
                  },
                },
              },
            },
          },
        },
      }),
    ]);

    return NextResponse.json({
      success: true,
      data: {
        products,
        pagination: {
          page,
          limit,
          totalCount,
          totalPages,
          hasNextPage,
          hasPrevPage,
        },
        filters: {
          coffeeTypes: coffeeTypes.map(item => ({
            value: item.coffeeType,
            count: item._count,
          })),
          grades: grades.map(item => ({
            value: item.grade,
            count: item._count,
          })),
          processingMethods: processingMethods.map(item => ({
            value: item.processing,
            count: item._count,
          })),
          origins: origins.map(item => ({
            value: item.origin,
            count: item._count,
          })),
          regions: regions.map(item => ({
            value: item.region,
            count: item._count,
          })),
          certifications: availableCertifications.map(cert => ({
            id: cert.id,
            name: cert.translations[0]?.name || cert.name,
            count: cert._count.products,
          })),
        },
      },
    });
  } catch (error) {
    // Error logging removed for production

    if (error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
