import { RFQEntity } from '@/domain/entities/rfq.entity';
import { IRFQRepository } from '@/domain/repositories/rfq.repository';
import { createScopedLogger } from '@/shared/utils/logger';

export interface GetRfqsRequest {
  page?: number | undefined;
  limit?: number | undefined;
  status?: string | undefined;
  priority?: string | undefined;
  companyName?: string | undefined;
  dateFrom?: Date | undefined;
  dateTo?: Date | undefined;
  sortBy?: 'submittedAt' | 'updatedAt' | 'priority' | 'status' | undefined;
  sortOrder?: 'asc' | 'desc' | undefined;
}

export interface GetRfqsResponse {
  rfqs: RFQEntity[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  success: boolean;
  message: string;
}

export class GetRfqsUseCase {
  private logger = createScopedLogger('GetRfqsUseCase');

  constructor(private rfqRepository: IRFQRepository) {}

  async execute(request: GetRfqsRequest = {}): Promise<GetRfqsResponse> {
    try {
      // Set defaults
      const page = request.page || 1;
      const limit = request.limit || 10;
      const sortBy = request.sortBy || 'submittedAt';
      const sortOrder = request.sortOrder || 'desc';

      // Validate pagination
      if (page < 1) {
        return {
          rfqs: [],
          total: 0,
          page: 1,
          limit,
          totalPages: 0,
          success: false,
          message: 'Page number must be greater than 0',
        };
      }

      if (limit < 1 || limit > 100) {
        return {
          rfqs: [],
          total: 0,
          page,
          limit: 10,
          totalPages: 0,
          success: false,
          message: 'Limit must be between 1 and 100',
        };
      }

      // Build filter criteria
      const filters: any = {};

      if (request.status) {
        filters.status = request.status;
      }

      if (request.priority) {
        filters.priority = request.priority;
      }

      if (request.companyName) {
        filters.companyName = {
          contains: request.companyName,
          mode: 'insensitive',
        };
      }

      if (request.dateFrom || request.dateTo) {
        filters.submittedAt = {};
        if (request.dateFrom) {
          filters.submittedAt.gte = request.dateFrom;
        }
        if (request.dateTo) {
          filters.submittedAt.lte = request.dateTo;
        }
      }

      // Get RFQs from repository
      const searchCriteria: any = {
        status: request.status as any,
        priority: request.priority as any,
        submittedAfter: request.dateFrom,
        submittedBefore: request.dateTo,
        page,
        limit,
        sortBy,
        sortOrder,
      };

      // Only add clientCompany if companyName is provided
      if (request.companyName) {
        searchCriteria.clientCompany = request.companyName;
      }

      const result = await this.rfqRepository.search(searchCriteria);

      const totalPages = Math.ceil(result.total / limit);

      return {
        rfqs: result.rfqs,
        total: result.total,
        page,
        limit,
        totalPages,
        success: true,
        message: 'RFQs retrieved successfully',
      };
    } catch (error) {
      // Application layer error logging removed for production
      return {
        rfqs: [],
        total: 0,
        page: request.page || 1,
        limit: request.limit || 10,
        totalPages: 0,
        success: false,
        message:
          error instanceof Error ? error.message : 'Failed to retrieve RFQs',
      };
    }
  }
}

import { IEmailService } from '@/application/services/email.service';
import { NotificationService } from '@/application/services/notification.service';
import { RFQEntity, type RFQ } from '@/domain/entities/rfq.entity';
import { IRFQRepository } from '@/domain/repositories/rfq.repository';
import { createScopedLogger } from '@/shared/utils/logger';

export interface SubmitRfqRequest {
  // Product Requirements
  productType: string[];
  grade: string[];
  origin: string[];
  processingMethod: string[];
  certifications: string[];

  // Quantity & Delivery
  quantity: number;
  quantityUnit: string;
  deliveryTerms: string;
  targetPrice: number;
  currency: string;
  deliveryDate: Date;
  deliveryLocation: string;

  // Recurring Order
  isRecurringOrder?: boolean | undefined;
  recurringFrequency?:
    | 'MONTHLY'
    | 'QUARTERLY'
    | 'SEMI_ANNUAL'
    | 'ANNUAL'
    | undefined;

  // Payment Terms
  paymentTerms: string;
  paymentMethod: string[];

  // Company Information
  companyName: string;
  contactPerson: string;
  email: string;
  phone: string;
  country: string;
  businessType: string;

  // Additional Details
  additionalRequirements?: string | undefined;
  sampleRequired: boolean;
  urgency: 'low' | 'medium' | 'high';

  // Metadata
  locale?: string | undefined;
}

export interface SubmitRfqResponse {
  rfq: RFQEntity;
  rfqNumber: string;
  success: boolean;
  message: string;
}

export class SubmitRfqUseCase {
  private logger = createScopedLogger('SubmitRfqUseCase');

  constructor(
    private rfqRepository: IRFQRepository,
    private emailService: IEmailService,
    private notificationService: NotificationService
  ) {}

  async execute(request: SubmitRfqRequest): Promise<SubmitRfqResponse> {
    try {
      // Validate required fields
      this.validateRequest(request);

      // Generate RFQ number
      const rfqNumber = this.generateRfqNumber();

      // Create RFQ entity
      const now = new Date();
      const rfqData: RFQ = {
        id: crypto.randomUUID(),
        rfqNumber,
        status: 'PENDING',
        priority:
          request.urgency === 'high'
            ? 'HIGH'
            : request.urgency === 'medium'
              ? 'MEDIUM'
              : 'LOW',

        productRequirements: {
          coffeeType: request.productType[0] as any, // Take first type
          grade: request.grade[0],
          processingMethod: request.processingMethod[0],
          origin: request.origin[0],
          certifications: request.certifications as any[],
        },

        quantityRequirements: {
          quantity: request.quantity,
          unit: request.quantityUnit as any,
          isRecurringOrder: request.isRecurringOrder || false,
          recurringFrequency: request.isRecurringOrder
            ? (request.recurringFrequency as any)
            : undefined,
        },

        deliveryRequirements: {
          incoterms: request.deliveryTerms as any,
          destinationPort: request.deliveryLocation,
          destinationCountry: request.country,
          preferredDeliveryDate: request.deliveryDate,
          latestDeliveryDate: request.deliveryDate,
          packaging: 'JUTE_BAGS_60KG' as any, // Default packaging
        },

        paymentTerms: {
          preferredCurrency: request.currency as any,
          paymentMethod: request.paymentMethod[0] as any,
          paymentTerms: request.paymentTerms,
        },

        companyInfo: {
          companyName: request.companyName,
          contactPerson: request.contactPerson,
          email: request.email,
          phone: request.phone,
          address: {
            street: '',
            city: '',
            postalCode: '',
            country: request.country,
          },
          businessType: request.businessType as any,
        },

        additionalRequirements: request.additionalRequirements,
        sampleRequired: request.sampleRequired,
        submittedAt: now,
        lastActivityAt: now,
        createdAt: now,
        updatedAt: now,
        updatedBy: crypto.randomUUID(), // System user ID
      };

      // Create RFQ entity and prepare data for repository
      const rfqEntity = new RFQEntity(rfqData);

      // Extract data without id, updatedAt for repository
      const {
        id: _id,
        updatedAt: _updatedAt,
        ...entityDataForRepo
      } = rfqEntity.toJSON();
      const savedRfq = await this.rfqRepository.create(
        entityDataForRepo as Omit<
          RFQ,
          'id' | 'rfqNumber' | 'submittedAt' | 'updatedAt'
        >
      );

      // Send confirmation email to customer
      await this.sendCustomerConfirmation(savedRfq);

      // Send notification to admin
      await this.sendAdminNotification(savedRfq);

      // Send internal notification
      await this.notificationService.sendAdminNotification(
        `New RFQ submitted: ${rfqNumber} from ${request.companyName}`
      );

      return {
        rfq: savedRfq,
        rfqNumber,
        success: true,
        message: 'RFQ submitted successfully',
      };
    } catch (error) {
      // Application layer error logging removed for production
      throw new Error('Failed to submit RFQ');
    }
  }

  private validateRequest(request: SubmitRfqRequest): void {
    const requiredFields = [
      'productType',
      'quantity',
      'quantityUnit',
      'deliveryTerms',
      'companyName',
      'contactPerson',
      'email',
      'phone',
      'country',
    ];

    for (const field of requiredFields) {
      if (!request[field as keyof SubmitRfqRequest]) {
        throw new Error(`Missing required field: ${field}`);
      }
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(request.email)) {
      throw new Error('Invalid email format');
    }

    // Validate quantity
    if (request.quantity <= 0) {
      throw new Error('Quantity must be greater than 0');
    }
  }

  private generateRfqNumber(): string {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');

    // Use timestamp for unique numbering
    return `RFQ-${year}${month}${day}-${hours}${minutes}${seconds}`;
  }

  private async sendCustomerConfirmation(rfq: RFQEntity): Promise<void> {
    try {
      const subject = `RFQ Confirmation - ${rfq.rfqNumber}`;
      const content = `
        Dear ${rfq.companyInfo.contactPerson},
        
        Thank you for submitting your RFQ ${rfq.rfqNumber}.
        
        Company: ${rfq.companyInfo.companyName}
        Product Type: ${rfq.productRequirements.coffeeType}
        Quantity: ${rfq.quantityRequirements.quantity} ${rfq.quantityRequirements.unit}
        
        We will review your request and get back to you within 24 hours.
        
        Best regards,
        The Great Beans Team
      `;

      await this.emailService.sendEmail(
        rfq.companyInfo.email,
        subject,
        content
      );
    } catch (error) {
      // Application layer error logging removed for production
      // Don't throw error to prevent RFQ submission failure
    }
  }

  private async sendAdminNotification(rfq: RFQEntity): Promise<void> {
    try {
      const adminEmail = process.env.ADMIN_EMAIL || 'admin@greatbeans.com';
      const subject = `New RFQ Submitted - ${rfq.rfqNumber}`;
      const content = `
        New RFQ has been submitted:
        
        RFQ Number: ${rfq.rfqNumber}
        Company: ${rfq.companyInfo.companyName}
        Contact: ${rfq.companyInfo.contactPerson}
        Email: ${rfq.companyInfo.email}
        Product: ${rfq.productRequirements.coffeeType}
        Quantity: ${rfq.quantityRequirements.quantity} ${rfq.quantityRequirements.unit}
        Priority: ${rfq.priority}
        
        Please review and assign to appropriate team member.
      `;

      await this.emailService.sendEmail(adminEmail, subject, content);
    } catch (error) {
      // Application layer error logging removed for production
      // Don't throw error to prevent RFQ submission failure
    }
  }
}

import { NotificationService } from '@/application/services/notification.service';
import { RFQEntity, RFQStatus, type RFQ } from '@/domain/entities/rfq.entity';
import { IRFQRepository } from '@/domain/repositories/rfq.repository';
import { createScopedLogger } from '@/shared/utils/logger';

export interface UpdateRfqStatusRequest {
  id: string;
  status: RFQStatus;
  notes?: string;
  updatedBy?: string;
}

export interface UpdateRfqStatusResponse {
  rfq: RFQEntity | null;
  success: boolean;
  message: string;
}

export class UpdateRfqStatusUseCase {
  private logger = createScopedLogger('UpdateRfqStatusUseCase');

  constructor(
    private rfqRepository: IRFQRepository,
    private notificationService: NotificationService
  ) {}

  async execute(
    request: UpdateRfqStatusRequest
  ): Promise<UpdateRfqStatusResponse> {
    try {
      // Validate input
      if (!request.id) {
        return {
          rfq: null,
          success: false,
          message: 'RFQ ID is required',
        };
      }

      if (!request.status) {
        return {
          rfq: null,
          success: false,
          message: 'Status is required',
        };
      }

      // Validate status
      const validStatuses = [
        'pending',
        'under_review',
        'quoted',
        'accepted',
        'rejected',
        'expired',
      ];
      if (!validStatuses.includes(request.status)) {
        return {
          rfq: null,
          success: false,
          message: 'Invalid status provided',
        };
      }

      // Get existing RFQ
      const existingRfq = await this.rfqRepository.findById(request.id);
      if (!existingRfq) {
        return {
          rfq: null,
          success: false,
          message: 'RFQ not found',
        };
      }

      // Update RFQ status
      const updateData: Partial<RFQ> = {
        status: request.status as RFQStatus,
        updatedAt: new Date(),
      };

      if (request.notes) {
        updateData.notes = request.notes;
      }

      if (request.updatedBy) {
        updateData.updatedBy = request.updatedBy;
      }

      // Update in repository
      const updatedRfq = await this.rfqRepository.update(
        request.id,
        updateData
      );

      if (!updatedRfq) {
        return {
          rfq: null,
          success: false,
          message: 'Failed to update RFQ status',
        };
      }

      // Send notification if status changed significantly
      if (this.shouldNotifyStatusChange(existingRfq.status, request.status)) {
        try {
          await this.notificationService.sendAdminNotification(
            `RFQ ${updatedRfq.rfqNumber} status changed from ${existingRfq.status} to ${request.status}`
          );
        } catch (notificationError) {
          // Application layer error logging removed for production
          // Don't fail the entire operation if notification fails
        }
      }

      return {
        rfq: updatedRfq,
        success: true,
        message: 'RFQ status updated successfully',
      };
    } catch (error) {
      // Application layer error logging removed for production
      return {
        rfq: null,
        success: false,
        message:
          error instanceof Error
            ? error.message
            : 'Failed to update RFQ status',
      };
    }
  }

  private shouldNotifyStatusChange(
    oldStatus: string,
    newStatus: string
  ): boolean {
    // Notify on significant status changes
    const significantChanges = [
      { from: 'pending', to: 'under_review' },
      { from: 'under_review', to: 'quoted' },
      { from: 'quoted', to: 'accepted' },
      { from: 'quoted', to: 'rejected' },
      { from: 'pending', to: 'expired' },
      { from: 'under_review', to: 'expired' },
    ];

    return significantChanges.some(
      change => change.from === oldStatus && change.to === newStatus
    );
  }
}

