export function LogisticsCostEstimator({
  className,
  onEstimateCalculated,
}: LogisticsCostEstimatorProps) {
  const t = useTranslations('logistics.estimator');
  const { config: _config, locale: _locale, formatCurrency: _formatCurrency } = useMarket();
  const { majorPorts, preferredIncoterms: _preferredIncoterms } = useMarketShipping();

  // Get translated arrays
  const SHIPPING_METHODS = getShippingMethods(t);
  const CONTAINER_TYPES = getContainerTypes(t);
  const INCOTERMS_OPTIONS = getIncoterms(t);

  // Form state
  const [formData, setFormData] = useState({
    quantity: '',
    unit: 'MT',
    originPort: '',
    destinationPort: '',
    destinationCountry: '',
    incoterms: 'FOB',
    shippingMethod: 'SEA_FREIGHT',
    containerType: '20FT',
    insuranceValue: '',
  });

  // Calculation state
  const [estimate, setEstimate] = useState<ShippingEstimate | null>(null);
  const [isCalculating, setIsCalculating] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Get available ports based on locale
  const availablePorts = useMemo(() => {
    return (
      majorPorts || [
        { name: 'Ho Chi Minh City', code: 'VNSGN', country: 'Vietnam' },
        { name: 'Da Nang', code: 'VNDAD', country: 'Vietnam' },
        { name: 'Hai Phong', code: 'VNHPH', country: 'Vietnam' },
      ]
    );
  }, [majorPorts]);

  // Validation
  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.quantity || parseFloat(formData.quantity) <= 0) {
      newErrors.quantity = t('errors.quantityRequired');
    }

    if (!formData.originPort) {
      newErrors.originPort = t('errors.originPortRequired');
    }

    if (!formData.destinationPort) {
      newErrors.destinationPort = t('errors.destinationPortRequired');
    }

    if (!formData.destinationCountry) {
      newErrors.destinationCountry = t('errors.destinationCountryRequired');
    }

    if (formData.insuranceValue && parseFloat(formData.insuranceValue) <= 0) {
      newErrors.insuranceValue = t('errors.insuranceValueInvalid');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Calculate shipping estimate
  const calculateEstimate = async () => {
    if (!validateForm()) return;

    setIsCalculating(true);

    try {
      const quantity = parseFloat(formData.quantity);
      const insuranceValue =
        parseFloat(formData.insuranceValue) || quantity * 3000; // Default $3000/MT

      // Get origin and destination port data
      const _originPortData = availablePorts.find(
        p => p.code === formData.originPort
      );
      const _destinationPortData = {
        name: formData.destinationPort || '',
        code: formData.destinationPort
          ? formData.destinationPort.toUpperCase()
          : '',
        country: formData.destinationCountry || '',
        coordinates: { lat: 0, lng: 0 }, // Would be fetched from API in real implementation
      };

      // Base shipping calculation
      const shippingMethod = SHIPPING_METHODS.find(
        m => m.value === formData.shippingMethod
      )!;
      const baseRate = 150; // Base rate per MT in USD
      const baseShippingCost =
        quantity * baseRate * shippingMethod.costMultiplier;

      // Additional costs based on Incoterms
      let insuranceCost = 0;
      let handlingCost = 0;
      let documentationCost = 0;

      switch (formData.incoterms) {
        case 'EXW':
          // Buyer handles everything
          break;
        case 'FCA':
          handlingCost = quantity * 15;
          documentationCost = 200;
          break;
        case 'FOB':
          handlingCost = quantity * 25;
          documentationCost = 300;
          break;
        case 'CFR':
          handlingCost = quantity * 25;
          documentationCost = 300;
          break;
        case 'CIF':
          handlingCost = quantity * 25;
          documentationCost = 300;
          insuranceCost = insuranceValue * 0.002; // 0.2% of cargo value
          break;
        case 'DAP':
          handlingCost = quantity * 35;
          documentationCost = 500;
          insuranceCost = insuranceValue * 0.002;
          break;
        case 'DDP':
          handlingCost = quantity * 45;
          documentationCost = 800;
          insuranceCost = insuranceValue * 0.002;
          break;
      }

      const totalCost =
        baseShippingCost + insuranceCost + handlingCost + documentationCost;

      const breakdown = [
        {
          label: 'Base Shipping Cost',
          amount: baseShippingCost,
          description: `${quantity} MT ├ù $${baseRate} ├ù ${shippingMethod.costMultiplier}`,
        },
        ...(handlingCost > 0
          ? [
              {
                label: 'Handling & Port Charges',
                amount: handlingCost,
                description: 'Port handling and loading charges',
              },
            ]
          : []),
        ...(insuranceCost > 0
          ? [
              {
                label: 'Marine Insurance',
                amount: insuranceCost,
                description: '0.2% of cargo value',
              },
            ]
          : []),
        ...(documentationCost > 0
          ? [
              {
                label: 'Documentation',
                amount: documentationCost,
                description: 'Export documentation and certificates',
              },
            ]
          : []),
      ];

      const newEstimate: ShippingEstimate = {
        baseShippingCost,
        insuranceCost,
        handlingCost,
        documentationCost,
        totalCost,
        currency: 'USD',
        transitDays: Math.round(
          (shippingMethod.transitDays.min + shippingMethod.transitDays.max) / 2
        ),
        incoterms: formData.incoterms,
        shippingMethod: formData.shippingMethod,
        containerType: formData.containerType,
        breakdown,
      };

      setEstimate(newEstimate);
      onEstimateCalculated?.(newEstimate);
    } catch (error) {
      // Shipping calculation error handling removed for production
    } finally {
      setIsCalculating(false);
    }
  };

  const _selectedIncoterm = INCOTERMS_OPTIONS.find(
    opt => opt.value === formData.incoterms
  );
  const _selectedShippingMethod = SHIPPING_METHODS.find(
    m => m.value === formData.shippingMethod
  );

  return (
    <TooltipProvider>
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calculator className="h-5 w-5" />
            {t('title')}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Shipment Details */}
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="quantity">{t('quantity')} *</Label>
              <div className="flex gap-2">
                <Input
                  id="quantity"
                  type="number"
                  placeholder={t('quantity')}
                  value={formData.quantity}
                  onChange={e =>
                    setFormData(prev => ({ ...prev, quantity: e.target.value }))
                  }
                  className={errors.quantity ? 'border-red-500' : ''}
                />
                <Select
                  value={formData.unit}
                  onValueChange={value =>
                    setFormData(prev => ({ ...prev, unit: value }))
                  }
                >
                  <SelectTrigger className="w-20">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="MT">MT</SelectItem>
                    <SelectItem value="KG">KG</SelectItem>
                    <SelectItem value="LB">LB</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              {errors.quantity && (
                <p className="text-sm text-red-500">{errors.quantity}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="insuranceValue">{t('cargoValue')}</Label>
              <Input
                id="insuranceValue"
                type="number"
                placeholder={t('cargoValue')}
                value={formData.insuranceValue}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    insuranceValue: e.target.value,
                  }))
                }
                className={errors.insuranceValue ? 'border-red-500' : ''}
              />
              {errors.insuranceValue && (
                <p className="text-sm text-red-500">{errors.insuranceValue}</p>
              )}
            </div>
          </div>

          {/* Origin & Destination */}
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="originPort">{t('originPort')} *</Label>
              <Select
                value={formData.originPort}
                onValueChange={value =>
                  setFormData(prev => ({ ...prev, originPort: value }))
                }
              >
                <SelectTrigger
                  className={errors.originPort ? 'border-red-500' : ''}
                >
                  <SelectValue placeholder={t('originPort')} />
                </SelectTrigger>
                <SelectContent>
                  {availablePorts.map(port => (
                    <SelectItem key={port.code} value={port.code}>
                      {port.name} ({port.code})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {errors.originPort && (
                <p className="text-sm text-red-500">{errors.originPort}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="destinationPort">{t('destinationPort')} *</Label>
              <Input
                id="destinationPort"
                placeholder={t('destinationPort')}
                value={formData.destinationPort}
                onChange={e =>
                  setFormData(prev => ({
                    ...prev,
                    destinationPort: e.target.value,
                  }))
                }
                className={errors.destinationPort ? 'border-red-500' : ''}
              />
              {errors.destinationPort && (
                <p className="text-sm text-red-500">{errors.destinationPort}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="destinationCountry">
              {t('destinationCountry')} *
            </Label>
            <Input
              id="destinationCountry"
              placeholder={t('destinationCountry')}
              value={formData.destinationCountry}
              onChange={e =>
                setFormData(prev => ({
                  ...prev,
                  destinationCountry: e.target.value,
                }))
              }
              className={errors.destinationCountry ? 'border-red-500' : ''}
            />
            {errors.destinationCountry && (
              <p className="text-sm text-red-500">
                {errors.destinationCountry}
              </p>
            )}
          </div>

          {/* Shipping Method */}
          <div className="space-y-2">
            <Label>{t('shippingMethod')}</Label>
            <div className="grid grid-cols-1 gap-2 md:grid-cols-3">
              {SHIPPING_METHODS.map(method => {
                const Icon = method.icon;
                return (
                  <Card
                    key={method.value}
                    className={`cursor-pointer transition-colors ${
                      formData.shippingMethod === method.value
                        ? 'border-primary bg-primary/5'
                        : 'hover:border-primary/50'
                    }`}
                    onClick={() =>
                      setFormData(prev => ({
                        ...prev,
                        shippingMethod: method.value,
                      }))
                    }
                  >
                    <CardContent className="p-3">
                      <div className="mb-1 flex items-center gap-2">
                        <Icon className="h-4 w-4" />
                        <span className="text-sm font-medium">
                          {method.label}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {method.description}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {method.transitDays.min}-{method.transitDays.max} days
                      </p>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </div>

          {/* Incoterms */}
          <div className="space-y-2">
            <Label>{t('incoterms')}</Label>
            <Select
              value={formData.incoterms}
              onValueChange={value =>
                setFormData(prev => ({ ...prev, incoterms: value }))
              }
            >
              <SelectTrigger>
                <SelectValue placeholder={t('incoterms')} />
              </SelectTrigger>
              <SelectContent>
                {INCOTERMS_OPTIONS.map(option => (
                  <SelectItem key={option.value} value={option.value}>
                    <div className="flex w-full items-center justify-between">
                      <span>{option.label}</span>
                      <Badge variant="outline" className="ml-2">
                        {option.sellerResponsibility}
                      </Badge>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {_selectedIncoterm && (
              <p className="text-sm text-muted-foreground">
                {_selectedIncoterm.description}
              </p>
            )}
          </div>

          {/* Container Type (for sea freight) */}
          {formData.shippingMethod === 'SEA_FREIGHT' && (
            <div className="space-y-2">
              <Label>{t('containerType')}</Label>
              <Select
                value={formData.containerType}
                onValueChange={value =>
                  setFormData(prev => ({ ...prev, containerType: value }))
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {CONTAINER_TYPES.map(container => (
                    <SelectItem key={container.value} value={container.value}>
                      <div className="flex w-full items-center justify-between">
                        <span>{container.label}</span>
                        <span className="ml-2 text-sm text-muted-foreground">
                          {container.capacity}
                        </span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Calculate Button */}
          <Button
            onClick={calculateEstimate}
            disabled={isCalculating}
            className="w-full bg-amber-600 text-white hover:bg-amber-700"
            size="lg"
          >
            {isCalculating ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                {t('calculating')}
              </>
            ) : (
              <>
                <Calculator className="mr-2 h-4 w-4" />
                {t('calculateButton')}
              </>
            )}
          </Button>

          {/* Results */}
          {estimate && (
            <div className="space-y-4">
              <Separator />
              <div>
                <h3 className="mb-3 font-semibold">{t('results.title')}</h3>

                {/* Summary */}
                <Card className="mb-4">
                  <CardContent className="p-4">
                    <div className="mb-2 flex items-center justify-between">
                      <span className="text-lg font-semibold">
                        {t('results.totalCost')}
                      </span>
                      <span className="text-2xl font-bold text-primary">
                        ${estimate.totalCost.toLocaleString()}
                      </span>
                    </div>
                    <div className="grid grid-cols-2 gap-4 text-sm text-muted-foreground">
                      <div>
                        <span className="block">
                          {t('results.transitTime')}
                        </span>
                        <span className="font-medium">
                          {estimate.transitDays} days
                        </span>
                      </div>
                      <div>
                        <span className="block">{t('results.incoterms')}</span>
                        <span className="font-medium">
                          {estimate.incoterms}
                        </span>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Cost Breakdown */}
                <div className="space-y-2">
                  <h4 className="font-medium">{t('results.costBreakdown')}</h4>
                  {estimate.breakdown.map((item, index) => (
                    <div
                      key={index}
                      className="flex items-center justify-between border-b py-2"
                    >
                      <div>
                        <span className="font-medium">{item.label}</span>
                        <Tooltip>
                          <TooltipTrigger>
                            <Info className="ml-1 inline h-3 w-3" />
                          </TooltipTrigger>
                          <TooltipContent>
                            <p>{item.description}</p>
                          </TooltipContent>
                        </Tooltip>
                      </div>
                      <span className="font-medium">
                        ${item.amount.toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>

                {/* Disclaimer */}
                <div className="mt-4 rounded-lg border border-yellow-200 bg-yellow-50 p-3">
                  <p className="text-sm text-yellow-800">
                    <strong>{t('disclaimer.title')}:</strong>{' '}
                    {t('disclaimer.text')}
                  </p>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </TooltipProvider>
  );
}

export default LogisticsCostEstimator;

'use client';

import {
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
  FileText,
  ArrowRight,
} from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useState } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/presentation/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import { Textarea } from '@/presentation/components/ui/textarea';

export type RFQStatus =
  | 'pending'
  | 'processing'
  | 'quoted'
  | 'accepted'
  | 'rejected'
  | 'expired';

interface StatusTransition {
  from: RFQStatus;
  to: RFQStatus;
  label: string;
  requiresNote?: boolean;
  confirmationMessage?: string;
}

interface RFQStatusManagerProps {
  currentStatus: RFQStatus;
  rfqId: string;
  onStatusChange: (newStatus: RFQStatus, note?: string) => Promise<void>;
  disabled?: boolean;
}

const statusConfig = {
  pending: {
    icon: Clock,
    color: 'bg-yellow-100 text-yellow-800 border-yellow-200',
    label: 'pending',
  },
  processing: {
    icon: AlertCircle,
    color: 'bg-blue-100 text-blue-800 border-blue-200',
    label: 'processing',
  },
  quoted: {
    icon: FileText,
    color: 'bg-purple-100 text-purple-800 border-purple-200',
    label: 'quoted',
  },
  accepted: {
    icon: CheckCircle,
    color: 'bg-green-100 text-green-800 border-green-200',
    label: 'accepted',
  },
  rejected: {
    icon: XCircle,
    color: 'bg-red-100 text-red-800 border-red-200',
    label: 'rejected',
  },
  expired: {
    icon: XCircle,
    color: 'bg-gray-100 text-gray-800 border-gray-200',
    label: 'expired',
  },
};

// Define allowed status transitions
const allowedTransitions: StatusTransition[] = [
  { from: 'pending', to: 'processing', label: 'Start Processing' },
  {
    from: 'pending',
    to: 'rejected',
    label: 'Reject Request',
    requiresNote: true,
    confirmationMessage: 'Are you sure you want to reject this RFQ?',
  },
  { from: 'processing', to: 'quoted', label: 'Provide Quote' },
  {
    from: 'processing',
    to: 'rejected',
    label: 'Reject Request',
    requiresNote: true,
    confirmationMessage: 'Are you sure you want to reject this RFQ?',
  },
  { from: 'quoted', to: 'accepted', label: 'Mark as Accepted' },
  {
    from: 'quoted',
    to: 'rejected',
    label: 'Mark as Rejected',
    requiresNote: true,
  },
  { from: 'quoted', to: 'expired', label: 'Mark as Expired' },
];

export function RFQStatusBadge({ status }: { status: RFQStatus }) {
  const t = useTranslations('rfq.status');
  const config = statusConfig[status];

  if (!config) {
    return (
      <Badge
        variant="outline"
        className="flex items-center gap-1 border-gray-200 bg-gray-100 text-gray-800"
      >
        <AlertCircle className="h-3 w-3" />
        {status}
      </Badge>
    );
  }

  const Icon = config.icon;

  return (
    <Badge
      variant="outline"
      className={`${config.color} flex items-center gap-1`}
    >
      <Icon className="h-3 w-3" />
      {t(config.label)}
    </Badge>
  );
}

export function RFQStatusManager({
  currentStatus,
  rfqId,
  onStatusChange,
  disabled = false,
}: RFQStatusManagerProps) {
  const t = useTranslations('statusManager');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedTransition, setSelectedTransition] =
    useState<StatusTransition | null>(null);
  const [note, setNote] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Get available transitions for current status
  const availableTransitions = allowedTransitions.filter(
    transition => transition.from === currentStatus
  );

  const handleTransitionSelect = (transition: StatusTransition) => {
    setSelectedTransition(transition);
    setNote('');
    setIsDialogOpen(true);
  };

  const handleConfirmTransition = async () => {
    if (!selectedTransition) return;

    setIsLoading(true);
    try {
      await onStatusChange(selectedTransition.to, note || undefined);
      setIsDialogOpen(false);
      setSelectedTransition(null);
      setNote('');
    } catch (error) {
      // Status update error handling removed for production
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    setIsDialogOpen(false);
    setSelectedTransition(null);
    setNote('');
  };

  if (availableTransitions.length === 0 || disabled) {
    return <RFQStatusBadge status={currentStatus} />;
  }

  return (
    <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
      <RFQStatusBadge status={currentStatus} />

      {availableTransitions.length === 1 && availableTransitions[0] ? (
        <Button
          variant="outline"
          size="sm"
          onClick={() => handleTransitionSelect(availableTransitions[0]!)}
          className="flex w-full items-center justify-center gap-1 sm:w-auto"
        >
          <ArrowRight className="h-3 w-3" />
          <span className="truncate">{availableTransitions[0].label}</span>
        </Button>
      ) : (
        <Select
          onValueChange={value => {
            const transition = availableTransitions.find(
              t => `${t.from}-${t.to}` === value
            );
            if (transition) handleTransitionSelect(transition);
          }}
        >
          <SelectTrigger className="w-full sm:w-auto sm:min-w-[180px]">
            <SelectValue placeholder={t('changeStatus')} />
          </SelectTrigger>
          <SelectContent>
            {availableTransitions.map(transition => (
              <SelectItem
                key={`${transition.from}-${transition.to}`}
                value={`${transition.from}-${transition.to}`}
              >
                <div className="flex items-center gap-2">
                  <ArrowRight className="h-3 w-3" />
                  <span className="truncate">{transition.label}</span>
                </div>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )}

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t('confirmTransition')}</DialogTitle>
            <DialogDescription>
              {selectedTransition?.confirmationMessage ||
                t('confirmTransitionDescription', {
                  from: selectedTransition?.from || '',
                  to: selectedTransition?.to || '',
                })}
            </DialogDescription>
          </DialogHeader>

          {selectedTransition?.requiresNote && (
            <div className="space-y-2">
              <label className="text-sm font-medium">
                {t('note')} {selectedTransition.requiresNote && '*'}
              </label>
              <Textarea
                value={note}
                onChange={e => setNote(e.target.value)}
                placeholder={t('notePlaceholder')}
                rows={3}
              />
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={handleCancel}>
              {t('cancel')}
            </Button>
            <Button
              onClick={handleConfirmTransition}
              disabled={
                isLoading || (selectedTransition?.requiresNote && !note.trim())
              }
            >
              {isLoading ? t('updating') : t('confirm')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Status History Component
interface StatusHistoryEntry {
  id: string;
  status: RFQStatus;
  timestamp: Date;
  note?: string;
  updatedBy: string;
}

interface RFQStatusHistoryProps {
  history: StatusHistoryEntry[];
}

export function RFQStatusHistory({ history }: RFQStatusHistoryProps) {
  const tHistory = useTranslations('rfq.statusHistory');
  const tStatus = useTranslations('rfq.status');

  // Safety check for history prop
  if (!history || !Array.isArray(history) || history.length === 0) {
    return (
      <div className="py-8 text-center text-muted-foreground">
        No status history available
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold sm:text-xl">{tHistory('title')}</h3>

      <div className="space-y-3">
        {history.map((entry, index) => {
          const config = statusConfig[entry.status];
          const Icon = config.icon;

          return (
            <div
              key={entry.id}
              className="flex items-start gap-3 rounded-lg border p-3 transition-shadow hover:shadow-sm"
            >
              <div className={`rounded-full p-2 ${config.color} flex-shrink-0`}>
                <Icon className="h-4 w-4" />
              </div>

              <div className="min-w-0 flex-1 space-y-1">
                <div className="flex flex-col gap-1 sm:flex-row sm:items-center sm:gap-2">
                  <span className="font-medium">{tStatus(config.label)}</span>
                  <span className="text-xs text-gray-500 sm:text-sm">
                    <span className="block sm:inline">
                      {entry.timestamp.toLocaleDateString()}
                    </span>
                    <span className="block sm:ml-1 sm:inline">
                      {entry.timestamp.toLocaleTimeString()}
                    </span>
                  </span>
                </div>

                <div className="text-xs text-gray-600 sm:text-sm">
                  {tHistory('updatedBy', { name: entry.updatedBy })}
                </div>

                {entry.note && (
                  <div className="rounded border-l-2 border-gray-200 bg-gray-50 p-2 text-xs sm:text-sm">
                    {entry.note}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";
import { cn } from "@/shared/utils/index";
import React, { useState, createContext, useContext } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { IconMenu2, IconX } from "@tabler/icons-react";

interface Links {
  label: string;
  href: string;
  icon: React.JSX.Element | React.ReactNode;
}

interface SidebarContextProps {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  animate: boolean;
}

const SidebarContext = createContext<SidebarContextProps | undefined>(
  undefined
);

export const useSidebar = () => {
  const context = useContext(SidebarContext);
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider");
  }
  return context;
};

export const SidebarProvider = ({
  children,
  open: openProp,
  setOpen: setOpenProp,
  animate = true,
}: {
  children: React.ReactNode;
  open?: boolean;
  setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
  animate?: boolean;
}) => {
  const [openState, setOpenState] = useState(false);

  const open = openProp !== undefined ? openProp : openState;
  const setOpen = setOpenProp !== undefined ? setOpenProp : setOpenState;

  return (
    <SidebarContext.Provider value={{ open, setOpen, animate: animate }}>
      {children}
    </SidebarContext.Provider>
  );
};

export const Sidebar = ({
  children,
  open,
  setOpen,
  animate,
}: {
  children: React.ReactNode;
  open?: boolean;
  setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
  animate?: boolean;
}) => {
  return (
    <SidebarProvider open={open ?? false} setOpen={setOpen ?? (() => {})} animate={animate ?? true}>
      {children}
    </SidebarProvider>
  );
};

export const SidebarBody = (props: React.ComponentProps<typeof motion.div>) => {
  return (
    <>
      <DesktopSidebar {...props} />
      <MobileSidebar {...(props as any)} />
    </>
  );
};

export const DesktopSidebar = ({
  className,
  children,
  ...props
}: React.ComponentProps<typeof motion.div>) => {
  const { open, setOpen, animate } = useSidebar();
  return (
    <>
      <motion.div
        className={cn(
          "h-full px-4 py-4 hidden  md:flex md:flex-col bg-neutral-100 dark:bg-neutral-800 w-[300px] shrink-0",
          className
        )}
        animate={{
          width: animate ? (open ? "300px" : "60px") : "300px",
        }}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        {...props}
      >
        {children}
      </motion.div>
    </>
  );
};

export const MobileSidebar = ({
  className,
  children,
  ...props
}: React.ComponentProps<"div">) => {
  const { open, setOpen } = useSidebar();
  return (
    <>
      <div
        className={cn(
          "h-10 px-4 py-4 flex flex-row md:hidden  items-center justify-between bg-neutral-100 dark:bg-neutral-800 w-full"
        )}
        {...props}
      >
        <div className="flex justify-end z-20 w-full">
          <IconMenu2
            className="text-neutral-800 dark:text-neutral-200"
            onClick={() => setOpen(!open)}
          />
        </div>
        <AnimatePresence>
          {open && (
            <motion.div
              initial={{ x: "-100%", opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: "-100%", opacity: 0 }}
              transition={{
                duration: 0.3,
                ease: "easeInOut",
              }}
              className={cn(
                "fixed h-full w-full inset-0 bg-white dark:bg-neutral-900 p-10 z-[100] flex flex-col justify-between",
                className
              )}
            >
              <div
                className="absolute right-10 top-10 z-50 text-neutral-800 dark:text-neutral-200"
                onClick={() => setOpen(!open)}
              >
                <IconX />
              </div>
              {children}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </>
  );
};

export const SidebarLink = ({
  link,
  className,
  ...props
}: {
  link: Links;
  className?: string;
}) => {
  const { open, animate } = useSidebar();
  return (
    <a
      href={link.href}
      className={cn(
        "flex items-center justify-start gap-2  group/sidebar py-2",
        className
      )}
      {...props}
    >
      {link.icon}

      <motion.span
        animate={{
          display: animate ? (open ? "inline-block" : "none") : "inline-block",
          opacity: animate ? (open ? 1 : 0) : 1,
        }}
        className="text-neutral-700 dark:text-neutral-200 text-sm group-hover/sidebar:translate-x-1 transition duration-150 whitespace-pre inline-block !p-0 !m-0"
      >
        {link.label}
      </motion.span>
    </a>
  );
};

