} from '../../../domain/entities/coffee-product.entity';
import { prisma } from '../prisma';

// Use actual Prisma types
type PrismaProductWithIncludes = Prisma.CoffeeProductGetPayload<{
  include: {
    translations: true;
    certifications: {
      include: {
        certification: true;
      };
    };
  };
}>;

export interface ICoffeeProductRepository {
