    );
  },

  // Link component
  a: ({ href, children, ...props }: ComponentProps<'a'>) => (
    <a
      href={href}
      className="text-amber-600 underline hover:text-amber-700"
      target={href?.startsWith('http') ? '_blank' : undefined}
      rel={href?.startsWith('http') ? 'noopener noreferrer' : undefined}
      {...props}
