                {/* Altitude Range */}
                <div>
                  <Label className="mb-2 block text-sm font-medium text-forest-700">
                    Altitude (MASL)
                  </Label>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <Label
                        htmlFor="minAltitude"
                        className="text-xs text-forest-600"
