'use client';

import {
  ChevronLeft,
  ChevronRight,
  ZoomIn,
  ZoomOut,
  Download,
  Share2,
  X,
  Maximize2,
  RotateCw,
} from 'lucide-react';
import Image from 'next/image';
import React, { useState, useEffect } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import { Card, CardContent } from '@/presentation/components/ui/card';

export interface GalleryImage {
  id: string;
  src: string;
  alt: string;
  title?: string;
  description?: string;
  category?: string;
  tags?: string[];
  downloadUrl?: string;
}

interface ImageGalleryProps {
  images: GalleryImage[];
  title?: string;
  className?: string;
  showThumbnails?: boolean;
  showCategories?: boolean;
  allowDownload?: boolean;
  allowShare?: boolean;
  autoPlay?: boolean;
  autoPlayInterval?: number;
}

export function ImageGallery({
  images,
  title,
  className = '',
  showThumbnails = true,
  showCategories = true,
  allowDownload = true,
  allowShare = true,
  autoPlay = false,
  autoPlayInterval = 5000,
}: ImageGalleryProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [isPlaying, setIsPlaying] = useState(autoPlay);

  // Filter images by category
  const filteredImages = selectedCategory
    ? images.filter(img => img.category === selectedCategory)
    : images;

  // Get unique categories
  const categories = Array.from(
    new Set(
      images
        .map(img => img.category)
        .filter((cat): cat is string => Boolean(cat))
    )
  );

  // Auto-play functionality
  useEffect(() => {
    if (isPlaying && filteredImages.length > 1) {
      const interval = setInterval(() => {
        setCurrentIndex(prev => (prev + 1) % filteredImages.length);
      }, autoPlayInterval);
      return () => clearInterval(interval);
    }
    return undefined;
  }, [isPlaying, filteredImages.length, autoPlayInterval]);

  const currentImage = filteredImages[currentIndex];

  const goToPrevious = () => {
    setCurrentIndex(
      prev => (prev - 1 + filteredImages.length) % filteredImages.length
    );
    setZoom(1);
    setRotation(0);
  };

  const goToNext = () => {
    setCurrentIndex(prev => (prev + 1) % filteredImages.length);
    setZoom(1);
    setRotation(0);
  };

  const openLightbox = (index: number) => {
    setCurrentIndex(index);
    setIsLightboxOpen(true);
    setZoom(1);
    setRotation(0);
  };

  const closeLightbox = () => {
    setIsLightboxOpen(false);
    setZoom(1);
    setRotation(0);
  };

  const handleDownload = async (image: GalleryImage) => {
    if (image.downloadUrl) {
      const link = document.createElement('a');
      link.href = image.downloadUrl;
      link.download = image.title || image.alt;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const handleShare = async (image: GalleryImage) => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: image.title || image.alt,
          text: image.description || image.alt,
          url: image.src,
        });
      } catch (error) {
        // Error sharing - silently fail
      }
    } else {
      // Fallback: copy to clipboard
      navigator.clipboard.writeText(image.src);
    }
  };

  if (filteredImages.length === 0) {
    return (
      <Card className={className}>
        <CardContent className="p-8 text-center">
          <div className="text-gray-500">No images available</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {title && (
        <h2 className="text-2xl font-semibold text-gray-900">{title}</h2>
      )}

      {/* Category Filter */}
      {showCategories && categories.length > 0 && (
        <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
          <Button
            variant={selectedCategory === null ? 'default' : 'outline'}
            size="sm"
            className="whitespace-nowrap text-xs sm:text-sm"
            onClick={() => setSelectedCategory(null)}
          >
            <span className="hidden sm:inline">All ({images.length})</span>
            <span className="sm:hidden">All</span>
          </Button>
          {categories.map(category => (
            <Button
              key={category}
              variant={selectedCategory === category ? 'default' : 'outline'}
              size="sm"
              className="whitespace-nowrap text-xs sm:text-sm"
              onClick={() => setSelectedCategory(category)}
            >
              <span className="hidden sm:inline">
                {category} (
                {images.filter(img => img.category === category).length})
              </span>
              <span className="sm:hidden">{category}</span>
            </Button>
          ))}
        </div>
      )}

      {/* Main Gallery */}
      {currentImage && (
        <Card>
          <CardContent className="p-0">
            {/* Main Image */}
            <div className="relative aspect-video overflow-hidden bg-gray-100">
              <Image
                src={currentImage.src}
                alt={currentImage.alt}
                fill
                className="cursor-pointer object-cover transition-transform hover:scale-105"
                onClick={() => openLightbox(currentIndex)}
              />

              {/* Navigation Arrows */}
              {filteredImages.length > 1 && (
                <>
                  <Button
                    variant="secondary"
                    size="icon"
                    className="absolute left-2 top-1/2 h-8 w-8 -translate-y-1/2 transform touch-manipulation bg-white/80 hover:bg-white sm:left-4 sm:h-10 sm:w-10"
                    onClick={goToPrevious}
                    aria-label="Previous image"
                  >
                    <ChevronLeft className="h-4 w-4 sm:h-5 sm:w-5" />
                  </Button>
                  <Button
                    variant="secondary"
                    size="icon"
                    className="absolute right-2 top-1/2 h-8 w-8 -translate-y-1/2 transform touch-manipulation bg-white/80 hover:bg-white sm:right-4 sm:h-10 sm:w-10"
                    onClick={goToNext}
                    aria-label="Next image"
                  >
                    <ChevronRight className="h-4 w-4 sm:h-5 sm:w-5" />
                  </Button>
                </>
              )}

              {/* Image Counter */}
              <div className="absolute bottom-2 left-2 rounded-full bg-black/50 px-2 py-1 text-xs text-white sm:bottom-4 sm:left-4 sm:px-3 sm:text-sm">
                {currentIndex + 1} / {filteredImages.length}
              </div>

              {/* Action Buttons */}
              <div className="absolute bottom-2 right-2 flex gap-1 sm:bottom-4 sm:right-4 sm:gap-2">
                <Button
                  variant="secondary"
                  size="icon"
                  className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-10 sm:w-10"
                  onClick={() => openLightbox(currentIndex)}
                  aria-label="View image in fullscreen"
                >
                  <Maximize2 className="h-3 w-3 sm:h-4 sm:w-4" />
                </Button>
                {allowDownload && currentImage.downloadUrl && (
                  <Button
                    variant="secondary"
                    size="icon"
                    className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-10 sm:w-10"
                    onClick={() => handleDownload(currentImage)}
                    aria-label="Download image"
                  >
                    <Download className="h-3 w-3 sm:h-4 sm:w-4" />
                  </Button>
                )}
                {allowShare && (
                  <Button
                    variant="secondary"
                    size="icon"
                    className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-10 sm:w-10"
                    onClick={() => handleShare(currentImage)}
                    aria-label="Share image"
                  >
                    <Share2 className="h-3 w-3 sm:h-4 sm:w-4" />
                  </Button>
                )}
              </div>

              {/* Auto-play Control */}
              {autoPlay && filteredImages.length > 1 && (
                <Button
                  variant="secondary"
                  size="sm"
                  className="absolute right-4 top-4 bg-white/80 hover:bg-white"
                  onClick={() => setIsPlaying(!isPlaying)}
                >
                  {isPlaying ? 'Pause' : 'Play'}
                </Button>
              )}
            </div>

            {/* Image Info */}
            <div className="p-4">
              <h3 className="mb-2 text-lg font-semibold">
                {currentImage.title || currentImage.alt}
              </h3>
              {currentImage.description && (
                <p className="mb-3 text-gray-600">{currentImage.description}</p>
              )}
              {currentImage.tags && currentImage.tags.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {currentImage.tags.map(tag => (
                    <Badge
                      key={`tag-${tag}`}
                      variant="secondary"
                      className="text-xs"
                    >
                      {tag}
                    </Badge>
                  ))}
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Thumbnails */}
      {showThumbnails && filteredImages.length > 1 && (
        <div className="grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10">
          {filteredImages.map((image, index) => (
            <button
              key={image.id}
              className={`aspect-square touch-manipulation overflow-hidden rounded-lg border-2 transition-all ${
                index === currentIndex
                  ? 'border-amber-500 ring-2 ring-amber-200'
                  : 'border-gray-200 hover:border-gray-300'
              }`}
              onClick={() => setCurrentIndex(index)}
              aria-label={`View image ${index + 1}: ${image.alt}`}
            >
              <Image
                src={image.src}
                alt={image.alt}
                fill
                className="object-cover"
              />
            </button>
          ))}
        </div>
      )}

      {/* Lightbox */}
      {isLightboxOpen && currentImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 p-4">
          <div className="relative max-h-full max-w-7xl">
            {/* Close Button */}
            <Button
              variant="secondary"
              size="icon"
              className="absolute right-4 top-4 z-10 bg-white/20 text-white hover:bg-white/30"
              onClick={closeLightbox}
            >
              <X className="h-4 w-4" />
            </Button>

            {/* Controls */}
            <div className="absolute left-4 top-4 z-10 flex gap-2">
              <Button
                variant="secondary"
                size="icon"
                className="bg-white/20 text-white hover:bg-white/30"
                onClick={() => setZoom(Math.max(0.5, zoom - 0.25))}
              >
                <ZoomOut className="h-4 w-4" />
              </Button>
              <Button
                variant="secondary"
                size="icon"
                className="bg-white/20 text-white hover:bg-white/30"
                onClick={() => setZoom(Math.min(3, zoom + 0.25))}
              >
                <ZoomIn className="h-4 w-4" />
              </Button>
              <Button
                variant="secondary"
                size="icon"
                className="bg-white/20 text-white hover:bg-white/30"
                onClick={() => setRotation((rotation + 90) % 360)}
              >
                <RotateCw className="h-4 w-4" />
              </Button>
            </div>

            {/* Navigation */}
            {filteredImages.length > 1 && (
              <>
                <Button
                  variant="secondary"
                  size="icon"
                  className="absolute left-4 top-1/2 -translate-y-1/2 transform bg-white/20 text-white hover:bg-white/30"
                  onClick={goToPrevious}
                  aria-label="Previous image"
                >
                  <ChevronLeft className="h-6 w-6" />
                </Button>
                <Button
                  variant="secondary"
                  size="icon"
                  className="absolute right-4 top-1/2 -translate-y-1/2 transform bg-white/20 text-white hover:bg-white/30"
                  onClick={goToNext}
                  aria-label="Next image"
                >
                  <ChevronRight className="h-6 w-6" />
                </Button>
              </>
            )}

            {/* Image */}
            <Image
              src={currentImage.src}
              alt={currentImage.alt}
              width={800}
              height={600}
              className="max-h-full max-w-full object-contain transition-transform"
              style={{
                transform: `scale(${zoom}) rotate(${rotation}deg)`,
              }}
            />

            {/* Image Info */}
            <div className="absolute bottom-4 left-4 right-4 rounded-lg bg-black/50 p-4 text-white">
              <h3 className="text-lg font-semibold">
                {currentImage.title || currentImage.alt}
              </h3>
              {currentImage.description && (
                <p className="mt-1 text-gray-200">{currentImage.description}</p>
              )}
              <div className="mt-2 flex items-center justify-between">
                <span className="text-sm text-gray-300">
                  {currentIndex + 1} of {filteredImages.length}
                </span>
                <div className="flex gap-2">
                  {allowDownload && currentImage.downloadUrl && (
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => handleDownload(currentImage)}
                    >
                      <Download className="mr-1 h-4 w-4" />
                      Download
                    </Button>
                  )}
                  {allowShare && (
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => handleShare(currentImage)}
                    >
                      <Share2 className="mr-1 h-4 w-4" />
                      Share
                    </Button>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import {
  ChevronLeft,
  ChevronRight,
  Play,
  Image as ImageIcon,
  Video,
  Download,
  Share2,
  Maximize2,
  Grid3X3,
} from 'lucide-react';
import Image from 'next/image';
import React, { useState, useEffect } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import { Card, CardContent } from '@/presentation/components/ui/card';

import { ImageGallery } from './ImageGallery';
import { VideoPlayer, type VideoSource } from './VideoPlayer';

export interface MediaItem {
  id: string;
  type: 'image' | 'video';
  title?: string;
  description?: string;
  category?: string;
  tags?: string[];

  // Image properties
  src?: string;
  alt?: string;
  downloadUrl?: string;

  // Video properties
  sources?: VideoSource[];
  poster?: string;
  chapters?: Array<{
    time: number;
    title: string;
    description?: string;
  }>;
}

interface MediaCarouselProps {
  items: MediaItem[];
  title?: string;
  className?: string;
  showThumbnails?: boolean;
  showCategories?: boolean;
  allowDownload?: boolean;
  allowShare?: boolean;
  autoPlay?: boolean;
  autoPlayInterval?: number;
  defaultView?: 'carousel' | 'grid';
}

export function MediaCarousel({
  items,
  title,
  className = '',
  showThumbnails = true,
  showCategories = true,
  allowDownload = true,
  allowShare = true,
  autoPlay = false,
  autoPlayInterval = 5000,
  defaultView = 'carousel',
}: MediaCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<'all' | 'image' | 'video'>(
    'all'
  );
  const [viewMode, setViewMode] = useState<'carousel' | 'grid'>(defaultView);
  const [isPlaying, setIsPlaying] = useState(autoPlay);

  // Filter items
  const filteredItems = items.filter(item => {
    const categoryMatch =
      !selectedCategory || item.category === selectedCategory;
    const typeMatch = selectedType === 'all' || item.type === selectedType;
    return categoryMatch && typeMatch;
  });

  // Get unique categories and types
  const categories = Array.from(
    new Set(
      items
        .map(item => item.category)
        .filter((cat): cat is string => Boolean(cat))
    )
  );
  const types = Array.from(new Set(items.map(item => item.type)));

  // Auto-play functionality for carousel
  useEffect(() => {
    if (isPlaying && viewMode === 'carousel' && filteredItems.length > 1) {
      const interval = setInterval(() => {
        setCurrentIndex(prev => (prev + 1) % filteredItems.length);
      }, autoPlayInterval);
      return () => clearInterval(interval);
    }
    return undefined;
  }, [isPlaying, viewMode, filteredItems.length, autoPlayInterval]);

  const currentItem = filteredItems[currentIndex];

  const goToPrevious = () => {
    setCurrentIndex(
      prev => (prev - 1 + filteredItems.length) % filteredItems.length
    );
  };

  const goToNext = () => {
    setCurrentIndex(prev => (prev + 1) % filteredItems.length);
  };

  const handleDownload = async (item: MediaItem) => {
    const downloadUrl = item.downloadUrl || item.src || item.sources?.[0]?.src;
    if (downloadUrl) {
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = item.title || `media-${item.id}`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const handleShare = async (item: MediaItem) => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: item.title || 'Media',
          text: item.description || item.title || 'Media',
          url: window.location.href,
        });
      } catch (error) {
        // Error sharing - silently fail
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
    }
  };

  if (filteredItems.length === 0) {
    return (
      <Card className={className}>
        <CardContent className="p-8 text-center">
          <div className="text-gray-500">No media available</div>
        </CardContent>
      </Card>
    );
  }

  // Grid view
  if (viewMode === 'grid') {
    return (
      <div className={`space-y-4 sm:space-y-6 ${className}`}>
        {title && (
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <h2 className="line-clamp-2 text-xl font-semibold text-gray-900 sm:text-2xl">
              {title}
            </h2>
            <div className="flex gap-2 self-start sm:self-auto">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setViewMode('carousel')}
                className="flex-shrink-0"
                aria-label="Switch to carousel view"
              >
                <ChevronLeft className="h-4 w-4 sm:mr-1" />
                <span className="hidden sm:inline">Carousel</span>
              </Button>
              <Button
                variant="default"
                size="sm"
                className="flex-shrink-0"
                aria-label="Grid view (current)"
              >
                <Grid3X3 className="h-4 w-4 sm:mr-1" />
                <span className="hidden sm:inline">Grid</span>
              </Button>
            </div>
          </div>
        )}

        {/* Filters */}
        <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
          {/* Type Filter */}
          <Button
            variant={selectedType === 'all' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setSelectedType('all')}
          >
            All ({items.length})
          </Button>
          {types.map(type => (
            <Button
              key={type}
              variant={selectedType === type ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSelectedType(type)}
              className="capitalize"
            >
              {type === 'image' ? (
                <ImageIcon className="mr-1 h-4 w-4" />
              ) : (
                <Video className="mr-1 h-4 w-4" />
              )}
              {type} ({items.filter(item => item.type === type).length})
            </Button>
          ))}

          {/* Category Filter */}
          {showCategories && categories.length > 0 && (
            <>
              <div className="mx-2 h-6 w-px bg-gray-300" />
              <Button
                variant={selectedCategory === null ? 'default' : 'outline'}
                size="sm"
                onClick={() => setSelectedCategory(null)}
              >
                All Categories
              </Button>
              {categories.map(category => (
                <Button
                  key={category}
                  variant={
                    selectedCategory === category ? 'default' : 'outline'
                  }
                  size="sm"
                  onClick={() => setSelectedCategory(category)}
                >
                  {category}
                </Button>
              ))}
            </>
          )}
        </div>

        {/* Grid */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-6 lg:grid-cols-3 xl:grid-cols-4">
          {filteredItems.map((item, index) => (
            <Card
              key={item.id}
              className="group overflow-hidden transition-shadow hover:shadow-lg"
            >
              <div className="relative aspect-video bg-gray-100">
                {item.type === 'image' ? (
                  <Image
                    src={item.src || ''}
                    alt={item.alt || item.title || ''}
                    fill
                    className="object-cover"
                  />
                ) : (
                  <div className="relative h-full w-full">
                    <Image
                      src={item.poster || '/placeholder-video.jpg'}
                      alt={item.title || ''}
                      fill
                      className="object-cover"
                    />
                    <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                      <Button
                        variant="secondary"
                        size="icon"
                        className="h-12 w-12 bg-white/20 text-white hover:bg-white/30 sm:h-14 sm:w-14"
                        onClick={() => {
                          setCurrentIndex(index);
                          setViewMode('carousel');
                        }}
                      >
                        <Play className="ml-1 h-6 w-6 sm:h-7 sm:w-7" />
                      </Button>
                    </div>
                  </div>
                )}

                {/* Type Badge */}
                <Badge
                  variant="secondary"
                  className="absolute left-2 top-2 bg-black/50 text-xs text-white"
                >
                  {item.type === 'image' ? (
                    <ImageIcon className="mr-1 h-3 w-3" />
                  ) : (
                    <Video className="mr-1 h-3 w-3" />
                  )}
                  {item.type}
                </Badge>

                {/* Actions - Always visible on mobile, hover on desktop */}
                <div className="absolute right-2 top-2 flex gap-1 opacity-100 transition-opacity sm:opacity-0 sm:group-hover:opacity-100">
                  <Button
                    variant="secondary"
                    size="icon"
                    className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-9 sm:w-9"
                    onClick={() => {
                      setCurrentIndex(index);
                      setViewMode('carousel');
                    }}
                    aria-label="View in carousel mode"
                  >
                    <Maximize2 className="h-3 w-3 sm:h-4 sm:w-4" />
                  </Button>
                  {allowDownload && (
                    <Button
                      variant="secondary"
                      size="icon"
                      className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-9 sm:w-9"
                      onClick={() => handleDownload(item)}
                      aria-label="Download media"
                    >
                      <Download className="h-3 w-3 sm:h-4 sm:w-4" />
                    </Button>
                  )}
                  {allowShare && (
                    <Button
                      variant="secondary"
                      size="icon"
                      className="h-8 w-8 touch-manipulation bg-white/80 hover:bg-white sm:h-9 sm:w-9"
                      onClick={() => handleShare(item)}
                      aria-label="Share media"
                    >
                      <Share2 className="h-3 w-3 sm:h-4 sm:w-4" />
                    </Button>
                  )}
                </div>
              </div>

              <CardContent className="p-4">
                <h3 className="mb-1 line-clamp-2 text-sm font-semibold">
                  {item.title || `${item.type} ${item.id}`}
                </h3>
                {item.description && (
                  <p className="mb-2 line-clamp-2 text-xs text-gray-600">
                    {item.description}
                  </p>
                )}
                {item.category && (
                  <Badge variant="outline" className="text-xs">
                    {item.category}
                  </Badge>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  // Carousel view
  return (
    <div className={`space-y-6 ${className}`}>
      {title && (
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-semibold text-gray-900">{title}</h2>
          <div className="flex gap-2">
            <Button variant="default" size="icon" aria-label="Previous media">
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              size="icon"
              onClick={() => setViewMode('grid')}
              aria-label="Switch to grid view"
            >
              <Grid3X3 className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        {/* Type Filter */}
        <Button
          variant={selectedType === 'all' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setSelectedType('all')}
        >
          All ({items.length})
        </Button>
        {types.map(type => (
          <Button
            key={type}
            variant={selectedType === type ? 'default' : 'outline'}
            size="sm"
            onClick={() => setSelectedType(type)}
            className="capitalize"
          >
            {type === 'image' ? (
              <ImageIcon className="mr-1 h-4 w-4" />
            ) : (
              <Video className="mr-1 h-4 w-4" />
            )}
            {type} ({items.filter(item => item.type === type).length})
          </Button>
        ))}

        {/* Category Filter */}
        {showCategories && categories.length > 0 && (
          <>
            <div className="mx-2 h-6 w-px bg-gray-300" />
            <Button
              variant={selectedCategory === null ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSelectedCategory(null)}
            >
              All Categories
            </Button>
            {categories.map(category => (
              <Button
                key={category}
                variant={selectedCategory === category ? 'default' : 'outline'}
                size="sm"
                onClick={() => setSelectedCategory(category)}
              >
                {category}
              </Button>
            ))}
          </>
        )}
      </div>

      {/* Main Media Display */}
      {currentItem && (
        <Card>
          <CardContent className="p-0">
            <div className="relative">
              {currentItem.type === 'image' ? (
                <ImageGallery
                  images={filteredItems
                    .filter(item => item.type === 'image')
                    .map(item => {
                      const galleryImage: any = {
                        id: item.id,
                        src: item.src!,
                        alt: item.alt || item.title || '',
                      };

                      if (item.title) galleryImage.title = item.title;
                      if (item.description)
                        galleryImage.description = item.description;
                      if (item.category) galleryImage.category = item.category;
                      if (item.tags) galleryImage.tags = item.tags;
                      if (item.downloadUrl)
                        galleryImage.downloadUrl = item.downloadUrl;

                      return galleryImage;
                    })}
                  showThumbnails={showThumbnails}
                  showCategories={false}
                  allowDownload={allowDownload}
                  allowShare={allowShare}
                />
              ) : (
                <VideoPlayer
                  sources={currentItem.sources || []}
                  {...(currentItem.title && { title: currentItem.title })}
                  {...(currentItem.description && {
                    description: currentItem.description,
                  })}
                  {...(currentItem.poster && { poster: currentItem.poster })}
                  {...(currentItem.chapters && {
                    chapters: currentItem.chapters,
                  })}
                  allowDownload={allowDownload}
                  allowShare={allowShare}
                />
              )}

              {/* Navigation for mixed content */}
              {filteredItems.length > 1 && (
                <>
                  <Button
                    variant="secondary"
                    size="icon"
                    className="absolute left-4 top-1/2 z-10 -translate-y-1/2 transform bg-white/80 hover:bg-white"
                    onClick={goToPrevious}
                    aria-label="Previous media item"
                  >
                    <ChevronLeft className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="secondary"
                    size="icon"
                    className="absolute right-4 top-1/2 z-10 -translate-y-1/2 transform bg-white/80 hover:bg-white"
                    onClick={goToNext}
                    aria-label="Next media item"
                  >
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                </>
              )}

              {/* Media Counter */}
              <div className="absolute bottom-4 left-4 z-10 rounded-full bg-black/50 px-3 py-1 text-sm text-white">
                {currentIndex + 1} / {filteredItems.length}
              </div>

              {/* Auto-play Control */}
              {autoPlay && filteredItems.length > 1 && (
                <Button
                  variant="secondary"
                  size="sm"
                  className="absolute right-4 top-4 z-10 bg-white/80 hover:bg-white"
                  onClick={() => setIsPlaying(!isPlaying)}
                >
                  {isPlaying ? 'Pause' : 'Play'}
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Thumbnails for mixed content */}
      {showThumbnails && filteredItems.length > 1 && (
        <div className="grid grid-cols-6 gap-2 md:grid-cols-8 lg:grid-cols-10">
          {filteredItems.map((item, index) => (
            <button
              key={item.id}
              className={`relative aspect-square overflow-hidden rounded-lg border-2 transition-all ${
                index === currentIndex
                  ? 'border-amber-500 ring-2 ring-amber-200'
                  : 'border-gray-200 hover:border-gray-300'
              }`}
              onClick={() => setCurrentIndex(index)}
              aria-label={`View ${item.type} ${index + 1}: ${item.title || item.alt || 'media item'}`}
            >
              <Image
                src={
                  item.type === 'image'
                    ? item.src || '/placeholder-image.jpg'
                    : item.poster || '/placeholder-video.jpg'
                }
                alt={item.title || item.alt || ''}
                fill
                className="object-cover"
              />
              {/* Type indicator */}
              <div className="absolute right-1 top-1">
                {item.type === 'image' ? (
                  <ImageIcon className="h-3 w-3 text-white drop-shadow" />
                ) : (
                  <Video className="h-3 w-3 text-white drop-shadow" />
                )}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import {
  Play,
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  Minimize,
  SkipBack,
  SkipForward,
  Settings,
  Download,
  Share2,
  Loader2,
} from 'lucide-react';
import React, { useState, useRef, useEffect } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';

export interface VideoSource {
  src: string;
  quality: string;
  type?: string;
}

export interface VideoChapter {
  time: number;
  title: string;
  description?: string;
}

interface VideoPlayerProps {
  sources: VideoSource[];
  title?: string;
  description?: string;
  poster?: string;
  chapters?: VideoChapter[];
  autoPlay?: boolean;
  loop?: boolean;
  muted?: boolean;
  controls?: boolean;
  allowDownload?: boolean;
  allowShare?: boolean;
  className?: string;
  onTimeUpdate?: (currentTime: number) => void;
  onEnded?: () => void;
}

export function VideoPlayer({
  sources,
  title,
  description,
  poster,
  chapters = [],
  autoPlay = false,
  loop = false,
  muted = false,
  controls = true,
  allowDownload = true,
  allowShare = true,
  className = '',
  onTimeUpdate,
  onEnded,
}: VideoPlayerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(muted);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedQuality, setSelectedQuality] = useState(
    sources[0]?.quality || 'auto'
  );
  const [showSettings, setShowSettings] = useState(false);
  const [buffered, setBuffered] = useState(0);

  const currentSource =
    sources.find(s => s.quality === selectedQuality) || sources[0];

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleLoadedMetadata = () => {
      setDuration(video.duration);
      setIsLoading(false);
    };

    const handleTimeUpdate = () => {
      setCurrentTime(video.currentTime);
      onTimeUpdate?.(video.currentTime);

      // Update buffered
      if (video.buffered.length > 0) {
        setBuffered(video.buffered.end(video.buffered.length - 1));
      }
    };

    const handleEnded = () => {
      setIsPlaying(false);
      onEnded?.();
    };

    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleVolumeChange = () => {
      setVolume(video.volume);
      setIsMuted(video.muted);
    };

    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    video.addEventListener('timeupdate', handleTimeUpdate);
    video.addEventListener('ended', handleEnded);
    video.addEventListener('play', handlePlay);
    video.addEventListener('pause', handlePause);
    video.addEventListener('volumechange', handleVolumeChange);

    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      video.removeEventListener('timeupdate', handleTimeUpdate);
      video.removeEventListener('ended', handleEnded);
      video.removeEventListener('play', handlePlay);
      video.removeEventListener('pause', handlePause);
      video.removeEventListener('volumechange', handleVolumeChange);
    };
  }, [onTimeUpdate, onEnded]);

  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;

    if (isPlaying) {
      video.pause();
    } else {
      video.play();
    }
  };

  const handleSeek = (time: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = time;
  };

  const handleVolumeChange = (newVolume: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.volume = newVolume;
    setVolume(newVolume);
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (!video) return;
    video.muted = !video.muted;
    setIsMuted(video.muted);
  };

  const toggleFullscreen = () => {
    const video = videoRef.current;
    if (!video) return;

    if (!isFullscreen) {
      if (video.requestFullscreen) {
        video.requestFullscreen();
      }
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
    setIsFullscreen(!isFullscreen);
  };

  const skipTime = (seconds: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = Math.max(
      0,
      Math.min(duration, video.currentTime + seconds)
    );
  };

  const changeQuality = (quality: string) => {
    const video = videoRef.current;
    if (!video) return;

    const currentTime = video.currentTime;
    const wasPlaying = isPlaying;

    setSelectedQuality(quality);
    setIsLoading(true);

    // After source change, restore time and play state
    setTimeout(() => {
      video.currentTime = currentTime;
      if (wasPlaying) {
        video.play();
      }
    }, 100);
  };

  const handleDownload = () => {
    if (!currentSource) return;
    const link = document.createElement('a');
    link.href = currentSource.src;
    link.download = title || 'video';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: title || 'Video',
          ...(description && { text: description }),
          url: window.location.href,
        });
      } catch (error) {
        // Error sharing - silently fail
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
    }
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  const progressPercentage = duration > 0 ? (currentTime / duration) * 100 : 0;
  const bufferedPercentage = duration > 0 ? (buffered / duration) * 100 : 0;

  return (
    <div className={`space-y-4 ${className}`}>
      {title && (
        <div>
          <h2 className="mb-2 text-2xl font-semibold text-gray-900">{title}</h2>
          {description && <p className="text-gray-600">{description}</p>}
        </div>
      )}

      <Card>
        <CardContent className="p-0">
          <div className="group relative aspect-video bg-black">
            {/* Video Element */}
            {currentSource ? (
              <video
                ref={videoRef}
                className="h-full w-full"
                poster={poster}
                autoPlay={autoPlay}
                loop={loop}
                muted={muted}
                playsInline
                onClick={togglePlay}
              >
                <source
                  src={currentSource.src}
                  type={currentSource.type || 'video/mp4'}
                />
                Your browser does not support the video tag.
              </video>
            ) : (
              <div className="flex h-full w-full items-center justify-center bg-gray-100">
                <p className="text-gray-500">No video source available</p>
              </div>
            )}

            {/* Loading Overlay */}
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-black/50">
                <Loader2 className="h-8 w-8 animate-spin text-white" />
              </div>
            )}

            {/* Play/Pause Overlay */}
            <div
              className="absolute inset-0 flex cursor-pointer items-center justify-center opacity-0 transition-opacity group-hover:opacity-100"
              onClick={togglePlay}
            >
              <Button
                variant="secondary"
                size="icon"
                className="h-16 w-16 bg-white/20 text-white hover:bg-white/30"
                aria-label={isPlaying ? 'Pause video' : 'Play video'}
              >
                {isPlaying ? (
                  <Pause className="h-8 w-8" />
                ) : (
                  <Play className="ml-1 h-8 w-8" />
                )}
              </Button>
            </div>

            {/* Controls */}
            {controls && (
              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4 opacity-0 transition-opacity group-hover:opacity-100">
                {/* Progress Bar */}
                <div className="mb-4">
                  <div
                    className="h-1 w-full cursor-pointer rounded-full bg-white/30"
                    onClick={e => {
                      const rect = e.currentTarget.getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const percentage = x / rect.width;
                      handleSeek(percentage * duration);
                    }}
                  >
                    {/* Buffered */}
                    <div
                      className="absolute h-full rounded-full bg-white/50"
                      style={{ width: `${bufferedPercentage}%` }}
                    />
                    {/* Progress */}
                    <div
                      className="relative h-full rounded-full bg-white"
                      style={{ width: `${progressPercentage}%` }}
                    >
                      <div className="absolute right-0 top-1/2 h-3 w-3 -translate-y-1/2 translate-x-1/2 transform rounded-full bg-white" />
                    </div>
                  </div>
                </div>

                {/* Control Buttons */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-white hover:bg-white/20"
                      onClick={togglePlay}
                      aria-label={isPlaying ? 'Pause video' : 'Play video'}
                    >
                      {isPlaying ? (
                        <Pause className="h-4 w-4" />
                      ) : (
                        <Play className="h-4 w-4" />
                      )}
                    </Button>

                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-white hover:bg-white/20"
                      onClick={() => skipTime(-10)}
                      aria-label="Skip back 10 seconds"
                    >
                      <SkipBack className="h-4 w-4" />
                    </Button>

                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-white hover:bg-white/20"
                      onClick={() => skipTime(10)}
                      aria-label="Skip forward 10 seconds"
                    >
                      <SkipForward className="h-4 w-4" />
                    </Button>

                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-white hover:bg-white/20"
                        onClick={toggleMute}
                        aria-label={isMuted ? 'Unmute video' : 'Mute video'}
                      >
                        {isMuted ? (
                          <VolumeX className="h-4 w-4" />
                        ) : (
                          <Volume2 className="h-4 w-4" />
                        )}
                      </Button>

                      <input
                        type="range"
                        min="0"
                        max="1"
                        step="0.1"
                        value={isMuted ? 0 : volume}
                        onChange={e =>
                          handleVolumeChange(parseFloat(e.target.value))
                        }
                        className="h-1 w-20 cursor-pointer appearance-none rounded-full bg-white/30"
                      />
                    </div>

                    <span className="text-sm text-white">
                      {formatTime(currentTime)} / {formatTime(duration)}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    {/* Quality Settings */}
                    <div className="relative">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-white hover:bg-white/20"
                        onClick={() => setShowSettings(!showSettings)}
                        aria-label="Video settings"
                      >
                        <Settings className="h-4 w-4" />
                      </Button>

                      {showSettings && (
                        <div className="absolute bottom-full right-0 mb-2 min-w-32 rounded-lg bg-black/90 p-2">
                          <div className="mb-2 text-sm font-medium text-white">
                            Quality
                          </div>
                          {sources.map(source => (
                            <button
                              key={source.quality}
                              className={`block w-full rounded px-2 py-1 text-left text-sm ${
                                selectedQuality === source.quality
                                  ? 'bg-white/20 text-white'
                                  : 'text-gray-300 hover:bg-white/10'
                              }`}
                              onClick={() => {
                                changeQuality(source.quality);
                                setShowSettings(false);
                              }}
                            >
                              {source.quality}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>

                    {allowDownload && (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-white hover:bg-white/20"
                        onClick={handleDownload}
                        aria-label="Download video"
                      >
                        <Download className="h-4 w-4" />
                      </Button>
                    )}

                    {allowShare && (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-white hover:bg-white/20"
                        onClick={handleShare}
                        aria-label="Share video"
                      >
                        <Share2 className="h-4 w-4" />
                      </Button>
                    )}

                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-white hover:bg-white/20"
                      onClick={toggleFullscreen}
                      aria-label={
                        isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'
                      }
                    >
                      {isFullscreen ? (
                        <Minimize className="h-4 w-4" />
                      ) : (
                        <Maximize className="h-4 w-4" />
                      )}
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Chapters */}
      {chapters.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Chapters</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {chapters.map((chapter, index) => (
                <button
                  key={`chapter-${chapter.time}-${chapter.title}`}
                  className={`w-full rounded-lg border p-3 text-left transition-colors ${(() => {
                    const nextChapter = chapters[index + 1];
                    return currentTime >= chapter.time &&
                      (index === chapters.length - 1 ||
                        (nextChapter && currentTime < nextChapter.time))
                      ? 'border-amber-500 bg-amber-50'
                      : 'border-gray-200 hover:bg-gray-50';
                  })()}`}
                  onClick={() => handleSeek(chapter.time)}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="font-medium">{chapter.title}</div>
                      {chapter.description && (
                        <div className="mt-1 text-sm text-gray-600">
                          {chapter.description}
                        </div>
                      )}
                    </div>
                    <Badge variant="secondary" className="text-xs">
                      {formatTime(chapter.time)}
                    </Badge>
                  </div>
                </button>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

