          <TabsContent value="timeline" className="mt-6">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="h-5 w-5" />
                  {t('detail.rfqTimeline')}
                </CardTitle>
                <CardDescription>
                  {t('detail.timelineDescription')}
