'use client';

import {
  Eye,
  Download,
  MessageSquare,
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
  Package,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ChevronUp,
  ChevronDown,
  MoreHorizontal as _MoreHorizontal,
} from 'lucide-react';
import { useTranslations } from 'next-intl';

import { formatDateTime } from '@/lib/date-utils';
import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import {
  DropdownMenu as _DropdownMenu,
  DropdownMenuContent as _DropdownMenuContent,
  DropdownMenuItem as _DropdownMenuItem,
  DropdownMenuSeparator as _DropdownMenuSeparator,
  DropdownMenuTrigger as _DropdownMenuTrigger,
} from '@/presentation/components/ui/dropdown-menu';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/presentation/components/ui/table';
import { useMarket } from '@/shared/hooks/useMarket';

export interface RFQItem {
  id: string;
  rfqNumber: string;
  status:
    | 'SUBMITTED'
    | 'UNDER_REVIEW'
    | 'QUOTED'
    | 'NEGOTIATING'
    | 'ACCEPTED'
    | 'REJECTED'
    | 'EXPIRED';
  priority: 'LOW' | 'MEDIUM' | 'HIGH' | 'URGENT';
  productType: string;
  quantity: number;
  unit: string;
  estimatedValue: number;
  currency: string;
  submittedAt: string;
  lastUpdate: string;
  responseDeadline: string;
  assignedTo?: string;
  companyName: string;
  contactPerson: string;
}

export interface PaginationConfig {
  page: number;
  pageSize: number;
  total: number;
}

interface RFQListTableProps {
  rfqs: RFQItem[];
  onViewRFQ: (rfq: RFQItem) => void;
  sortConfig: {
    field: string;
    direction: 'asc' | 'desc';
  };
  onSortChange: (config: { field: string; direction: 'asc' | 'desc' }) => void;
  pagination: {
    page: number;
    pageSize: number;
    total: number;
  };
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
  loading?: boolean;
  totalCount: number;
  filteredCount: number;
}

const getStatusConfig = (t: (key: string) => string) => ({
  SUBMITTED: {
    label: t('status.submitted'),
    color: 'bg-blue-100 text-blue-800',
    icon: Clock,
  },
  UNDER_REVIEW: {
    label: t('status.underReview'),
    color: 'bg-yellow-100 text-yellow-800',
    icon: AlertCircle,
  },
  QUOTED: {
    label: t('status.quoted'),
    color: 'bg-green-100 text-green-800',
    icon: CheckCircle,
  },
  NEGOTIATING: {
    label: t('status.negotiating'),
    color: 'bg-orange-100 text-orange-800',
    icon: MessageSquare,
  },
  ACCEPTED: {
    label: t('status.accepted'),
    color: 'bg-emerald-100 text-emerald-800',
    icon: CheckCircle,
  },
  REJECTED: {
    label: t('status.rejected'),
    color: 'bg-red-100 text-red-800',
    icon: XCircle,
  },
  EXPIRED: {
    label: t('status.expired'),
    color: 'bg-gray-100 text-gray-800',
    icon: Clock,
  },
});

const getPriorityConfig = (t: (key: string) => string) => ({
  LOW: { label: t('priority.low'), color: 'bg-gray-100 text-gray-800' },
  MEDIUM: { label: t('priority.medium'), color: 'bg-blue-100 text-blue-800' },
  HIGH: { label: t('priority.high'), color: 'bg-orange-100 text-orange-800' },
  URGENT: { label: t('priority.urgent'), color: 'bg-red-100 text-red-800' },
});

export function RFQListTable({
  rfqs,
  onViewRFQ,
  sortConfig,
  onSortChange,
  pagination,
  onPageChange,
  onPageSizeChange,
  loading = false,
  totalCount,
  filteredCount,
}: RFQListTableProps) {
  const t = useTranslations('rfq');
  const { locale, formatCurrency: marketFormatCurrency } = useMarket();

  const statusConfig = getStatusConfig(t);
  const priorityConfig = getPriorityConfig(t);

  // Handle sort
  const handleSort = (field: string) => {
    const direction =
      sortConfig.field === field && sortConfig.direction === 'asc'
        ? 'desc'
        : 'asc';
    onSortChange({ field, direction });
  };

  // Sortable header component
  const SortableHeader = ({
    field,
    children,
  }: {
    field: string;
    children: React.ReactNode;
  }) => (
    <TableHead
      className="cursor-pointer select-none hover:bg-gray-50"
      onClick={() => handleSort(field)}
    >
      <div className="flex items-center gap-1">
        {children}
        {sortConfig.field === field &&
          (sortConfig.direction === 'asc' ? (
            <ChevronUp className="h-4 w-4" />
          ) : (
            <ChevronDown className="h-4 w-4" />
          ))}
      </div>
    </TableHead>
  );

  const formatDateLocal = (dateString: string) => {
    return formatDateTime(new Date(dateString), locale);
  };

  const formatCurrencyLocal = (amount: number, _currency: string) => {
    return marketFormatCurrency(amount);
  };

  const getStatusIcon = (status: keyof typeof statusConfig) => {
    const Icon = statusConfig[status].icon;
    return <Icon className="h-4 w-4" />;
  };

  const isDeadlineUrgent = (deadline: string) => {
    const deadlineDate = new Date(deadline);
    const now = new Date();
    const diffHours =
      (deadlineDate.getTime() - now.getTime()) / (1000 * 60 * 60);
    return diffHours <= 24 && diffHours > 0;
  };

  const isDeadlineExpired = (deadline: string) => {
    const deadlineDate = new Date(deadline);
    const now = new Date();
    return deadlineDate < now;
  };

  const totalPages = Math.ceil(filteredCount / pagination.pageSize);
  const startItem = (pagination.page - 1) * pagination.pageSize + 1;
  const endItem = Math.min(
    pagination.page * pagination.pageSize,
    filteredCount
  );

  return (
    <Card>
      <CardHeader className="pb-4 sm:pb-6">
        <CardTitle className="text-lg sm:text-xl">{t('table.title')}</CardTitle>
        <CardDescription className="text-sm sm:text-base">
          {t('table.description')}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {/* Desktop Table View */}
        <div className="hidden overflow-x-auto lg:block">
          <Table>
            <TableHeader>
              <TableRow>
                <SortableHeader field="rfqNumber">
                  {t('table.headers.rfqNumber')}
                </SortableHeader>
                <SortableHeader field="productType">
                  {t('table.headers.productCompany')}
                </SortableHeader>
                <SortableHeader field="quantity">
                  {t('table.headers.quantity')}
                </SortableHeader>
                <SortableHeader field="estimatedValue">
                  {t('table.headers.estimatedValue')}
                </SortableHeader>
                <SortableHeader field="status">
                  {t('table.headers.status')}
                </SortableHeader>
                <SortableHeader field="priority">
                  {t('table.headers.priority')}
                </SortableHeader>
                <SortableHeader field="submittedAt">
                  {t('table.headers.submitted')}
                </SortableHeader>
                <SortableHeader field="responseDeadline">
                  {t('table.headers.deadline')}
                </SortableHeader>
                <SortableHeader field="assignedTo">
                  {t('table.headers.assignedTo')}
                </SortableHeader>
                <TableHead className="w-[100px]">
                  {t('table.headers.actions')}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                // Loading skeleton
                Array.from({ length: pagination.pageSize }).map((_, index) => (
                  <TableRow key={`skeleton-row-${index}`}>
                    {Array.from({ length: 10 }).map((_, cellIndex) => (
                      <TableCell key={`skeleton-cell-${index}-${cellIndex}`}>
                        <div className="h-4 w-full animate-pulse rounded bg-gray-200" />
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : rfqs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={10} className="h-32 text-center">
                    <div className="flex flex-col items-center justify-center">
                      <Package className="mb-4 h-12 w-12 text-gray-400" />
                      <h3 className="mb-2 text-lg font-medium text-gray-900">
                        {t('table.emptyState.title')}
                      </h3>
                      <p className="text-gray-500">
                        {t('table.emptyState.description')}
                      </p>
                      <Button
                        className="mt-4"
                        onClick={() => (window.location.href = '/en/quote')}
                      >
                        {t('table.emptyState.createButton')}
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                rfqs.map(rfq => (
                  <TableRow key={rfq.id} className="hover:bg-gray-50">
                    <TableCell className="font-medium">
                      <div className="flex flex-col">
                        <span className="font-mono text-sm">
                          {rfq.rfqNumber}
                        </span>
                        <span className="text-xs text-gray-500">
                          {t('table.labels.updated')}:{' '}
                          {formatDateLocal(rfq.lastUpdate)}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="max-w-[200px]">
                        <p className="truncate font-medium">
                          {rfq.productType}
                        </p>
                        <p className="truncate text-sm text-gray-500">
                          {rfq.companyName}
                        </p>
                        <p className="text-xs text-gray-400">
                          {t('table.labels.contact')}: {rfq.contactPerson}
                        </p>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="text-center">
                        <span className="font-medium">
                          {rfq.quantity.toLocaleString()}
                        </span>
                        <span className="ml-1 text-sm text-gray-500">
                          {rfq.unit}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <span className="font-medium">
                        {formatCurrencyLocal(rfq.estimatedValue, rfq.currency)}
                      </span>
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={`${statusConfig[rfq.status].color} flex w-fit items-center gap-1`}
                      >
                        {getStatusIcon(rfq.status)}
                        {statusConfig[rfq.status].label}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge className={priorityConfig[rfq.priority].color}>
                        {priorityConfig[rfq.priority].label}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-sm">
                      {formatDateLocal(rfq.submittedAt)}
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span
                          className={`text-sm ${
                            isDeadlineExpired(rfq.responseDeadline)
                              ? 'font-medium text-red-600'
                              : isDeadlineUrgent(rfq.responseDeadline)
                                ? 'font-medium text-orange-600'
                                : 'text-gray-600'
                          }`}
                        >
                          {formatDateLocal(rfq.responseDeadline)}
                        </span>
                        {isDeadlineExpired(rfq.responseDeadline) && (
                          <span className="text-xs text-red-500">
                            {t('table.labels.expired')}
                          </span>
                        )}
                        {isDeadlineUrgent(rfq.responseDeadline) &&
                          !isDeadlineExpired(rfq.responseDeadline) && (
                            <span className="text-xs text-orange-500">
                              {t('table.labels.urgent')}
                            </span>
                          )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {rfq.assignedTo ? (
                        <div className="flex items-center">
                          <div className="flex h-6 w-6 items-center justify-center rounded-full bg-forest-100 text-xs font-medium text-forest-700">
                            {rfq.assignedTo.charAt(0).toUpperCase()}
