                          <span className="ml-2 text-sm">{rfq.assignedTo}</span>
                        </div>
                      ) : (
                        <span className="text-sm text-gray-400">
                          {t('table.labels.unassigned')}
                        </span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => onViewRFQ(rfq)}
                          className="h-8 w-8 p-0"
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-8 w-8 p-0"
                        >
                          <Download className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-8 w-8 p-0"
                        >
                          <MessageSquare className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

        {/* Mobile Card View */}
        <div className="space-y-4 lg:hidden">
          {loading ? (
            // Loading skeleton for mobile
            Array.from({ length: pagination.pageSize }).map((_, index) => (
              <Card key={`mobile-skeleton-${index}`} className="p-4">
                <div className="space-y-3">
                  <div className="h-4 w-3/4 animate-pulse rounded bg-gray-200" />
                  <div className="h-3 w-1/2 animate-pulse rounded bg-gray-200" />
                  <div className="flex gap-2">
                    <div className="h-6 w-16 animate-pulse rounded bg-gray-200" />
                    <div className="h-6 w-16 animate-pulse rounded bg-gray-200" />
                  </div>
                </div>
              </Card>
            ))
          ) : rfqs.length === 0 ? (
            <Card className="p-8">
              <div className="flex flex-col items-center justify-center text-center">
                <Package className="mb-4 h-12 w-12 text-gray-400" />
                <h3 className="mb-2 text-lg font-medium text-gray-900">
                  {t('table.emptyState.title')}
                </h3>
                <p className="mb-4 text-gray-500">
                  {t('table.emptyState.description')}
                </p>
                <Button onClick={() => (window.location.href = '/en/quote')}>
                  {t('table.emptyState.createButton')}
                </Button>
              </div>
            </Card>
          ) : (
            rfqs.map(rfq => (
              <Card
                key={rfq.id}
                className="p-4 transition-shadow hover:shadow-md"
              >
                <div className="space-y-3">
                  {/* Header */}
                  <div className="flex items-start justify-between">
                    <div className="min-w-0 flex-1">
                      <h3 className="truncate font-mono text-sm font-medium">
                        {rfq.rfqNumber}
                      </h3>
                      <p className="truncate text-sm font-medium text-gray-900">
                        {rfq.productType}
                      </p>
                      <p className="truncate text-xs text-gray-500">
                        {rfq.companyName}
                      </p>
                    </div>
                    <div className="ml-2 flex flex-col items-end gap-1">
                      <Badge
                        className={`${statusConfig[rfq.status].color} text-xs`}
                      >
                        {getStatusIcon(rfq.status)}
                        {statusConfig[rfq.status].label}
                      </Badge>
                      <Badge
                        className={`${priorityConfig[rfq.priority].color} text-xs`}
                      >
                        {priorityConfig[rfq.priority].label}
                      </Badge>
                    </div>
                  </div>

                  {/* Details */}
                  <div className="grid grid-cols-2 gap-3 text-sm">
                    <div>
                      <span className="text-gray-500">
                        {t('table.labels.quantity')}:
                      </span>
                      <p className="font-medium">
                        {rfq.quantity.toLocaleString()} {rfq.unit}
                      </p>
                    </div>
                    <div>
                      <span className="text-gray-500">
                        {t('table.labels.estimatedValue')}:
                      </span>
                      <p className="font-medium">
                        {formatCurrencyLocal(rfq.estimatedValue, rfq.currency)}
                      </p>
                    </div>
                    <div>
                      <span className="text-gray-500">
                        {t('table.labels.submitted')}:
                      </span>
                      <p className="text-xs">
                        {formatDateLocal(rfq.submittedAt)}
                      </p>
                    </div>
                    <div>
                      <span className="text-gray-500">
                        {t('table.labels.deadline')}:
                      </span>
                      <p
                        className={`text-xs ${
                          isDeadlineExpired(rfq.responseDeadline)
                            ? 'font-medium text-red-600'
                            : isDeadlineUrgent(rfq.responseDeadline)
                              ? 'font-medium text-orange-600'
                              : 'text-gray-600'
                        }`}
                      >
                        {formatDateLocal(rfq.responseDeadline)}
                        {isDeadlineExpired(rfq.responseDeadline) && (
                          <span className="ml-1 text-red-500">
                            ({t('table.labels.expired')})
                          </span>
                        )}
                        {isDeadlineUrgent(rfq.responseDeadline) &&
                          !isDeadlineExpired(rfq.responseDeadline) && (
                            <span className="ml-1 text-orange-500">
                              ({t('table.labels.urgent')})
                            </span>
                          )}
                      </p>
                    </div>
                  </div>

                  {/* Contact & Assigned */}
                  <div className="flex items-center justify-between text-xs text-gray-500">
                    <span>
                      {t('table.labels.contact')}: {rfq.contactPerson}
                    </span>
                    {rfq.assignedTo ? (
                      <div className="flex items-center">
                        <div className="mr-1 flex h-5 w-5 items-center justify-center rounded-full bg-forest-100 text-xs font-medium text-forest-700">
                          {rfq.assignedTo.charAt(0).toUpperCase()}
                        </div>
                        <span>{rfq.assignedTo}</span>
                      </div>
                    ) : (
                      <span>{t('table.labels.unassigned')}</span>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex items-center justify-between border-t pt-2">
                    <span className="text-xs text-gray-500">
                      {t('table.labels.updated')}:{' '}
                      {formatDateLocal(rfq.lastUpdate)}
                    </span>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onViewRFQ(rfq)}
                        className="h-8 px-3 text-xs"
                      >
                        <Eye className="mr-1 h-3 w-3" />
                        {t('table.actions.view')}
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-8 w-8 p-0"
                      >
                        <Download className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-8 w-8 p-0"
                      >
                        <MessageSquare className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                </div>
              </Card>
            ))
          )}
        </div>

        {/* Pagination */}
        {!loading && rfqs.length > 0 && (
          <div className="flex flex-col items-start justify-between gap-4 border-t pt-4 sm:flex-row sm:items-center">
            <div className="flex flex-col items-start gap-2 sm:flex-row sm:items-center">
              <div className="flex items-center gap-2">
                <span className="text-xs text-gray-600 sm:text-sm">
                  {t('table.pagination.itemsPerPage')}:
                </span>
                <Select
                  value={pagination.pageSize.toString()}
                  onValueChange={value => onPageSizeChange(parseInt(value))}
                >
                  <SelectTrigger className="h-8 w-16">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="10">10</SelectItem>
                    <SelectItem value="25">25</SelectItem>
                    <SelectItem value="50">50</SelectItem>
                    <SelectItem value="100">100</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <span className="text-xs text-gray-600 sm:text-sm">
                {t('table.pagination.showing', {
                  start: startItem,
                  end: endItem,
                  total: filteredCount,
                })}
                {filteredCount !== totalCount && (
                  <span className="ml-1 text-xs">
                    {t('table.pagination.filtered', { total: totalCount })}
                  </span>
                )}
              </span>
            </div>

            <div className="flex items-center gap-1 sm:gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => onPageChange(1)}
                disabled={pagination.page === 1}
                className="h-8 w-8 p-0"
                title={t('table.pagination.firstPage')}
              >
                <ChevronsLeft className="h-3 w-3 sm:h-4 sm:w-4" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onPageChange(pagination.page - 1)}
                disabled={pagination.page === 1}
                className="h-8 w-8 p-0"
                title={t('table.pagination.previousPage')}
              >
                <ChevronLeft className="h-3 w-3 sm:h-4 sm:w-4" />
              </Button>

              <div className="flex items-center gap-1">
                {Array.from(
                  {
                    length: Math.min(
                      window.innerWidth < 640 ? 3 : 5,
                      totalPages
                    ),
                  },
                  (_, i) => {
                    let pageNum;
                    const maxPages = window.innerWidth < 640 ? 3 : 5;
                    if (totalPages <= maxPages) {
                      pageNum = i + 1;
                    } else if (
                      pagination.page <=
                      Math.floor(maxPages / 2) + 1
                    ) {
                      pageNum = i + 1;
                    } else if (
                      pagination.page >=
                      totalPages - Math.floor(maxPages / 2)
                    ) {
                      pageNum = totalPages - maxPages + 1 + i;
                    } else {
                      pageNum = pagination.page - Math.floor(maxPages / 2) + i;
                    }

                    return (
                      <Button
                        key={pageNum}
                        variant={
                          pagination.page === pageNum ? 'default' : 'outline'
                        }
                        size="sm"
                        onClick={() => onPageChange(pageNum)}
                        className="h-8 w-8 p-0 text-xs sm:text-sm"
                      >
                        {pageNum}
                      </Button>
                    );
                  }
                )}
              </div>

              <Button
                variant="outline"
                size="sm"
                onClick={() => onPageChange(pagination.page + 1)}
                disabled={pagination.page === totalPages}
                className="h-8 w-8 p-0"
                title={t('table.pagination.nextPage')}
              >
                <ChevronRight className="h-3 w-3 sm:h-4 sm:w-4" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onPageChange(totalPages)}
                disabled={pagination.page === totalPages}
                className="h-8 w-8 p-0"
                title={t('table.pagination.lastPage')}
              >
                <ChevronsRight className="h-3 w-3 sm:h-4 sm:w-4" />
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { Filter, X, ChevronDown } from 'lucide-react';
import { useState } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import { Checkbox } from '@/presentation/components/ui/checkbox';
import { Label } from '@/presentation/components/ui/label';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/presentation/components/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import { Separator } from '@/presentation/components/ui/separator';
import { cn } from '@/shared/utils/cn';

export interface FilterOption {
  value: string;
  label: string;
  count?: number;
}

export interface FilterGroup {
  id: string;
  label: string;
  type: 'select' | 'multiselect' | 'checkbox';
  options: FilterOption[];
  value?: string | string[];
  placeholder?: string;
}

export interface SortOption {
  value: string;
  label: string;
}

export interface SearchFiltersProps {
  filters: FilterGroup[];
  sortOptions: SortOption[];
  sortBy: string;
  onFilterChange: (filterId: string, value: string | string[]) => void;
  onSortChange: (sortBy: string) => void;
  onClearFilters: () => void;
  className?: string;
  showFilterCount?: boolean;
  compact?: boolean;
}

export function SearchFilters({
  filters,
  sortOptions,
  sortBy,
  onFilterChange,
  onSortChange,
  onClearFilters,
  className,
  showFilterCount = true,
  compact = false,
}: SearchFiltersProps) {
  const [isFiltersOpen, setIsFiltersOpen] = useState(false);

  // Count active filters
  const activeFiltersCount = filters.reduce((count, filter) => {
    if (filter.type === 'multiselect' && Array.isArray(filter.value)) {
      return count + filter.value.length;
    }
    if (filter.value && filter.value !== '') {
      return count + 1;
    }
    return count;
  }, 0);

  const handleFilterChange = (filterId: string, value: string | string[]) => {
    onFilterChange(filterId, value);
  };

  const handleMultiSelectChange = (
    filterId: string,
    optionValue: string,
    checked: boolean
  ) => {
    const filter = filters.find(f => f.id === filterId);
    if (!filter) return;

    const currentValues = Array.isArray(filter.value) ? filter.value : [];
    let newValues: string[];

    if (checked) {
      newValues = [...currentValues, optionValue];
    } else {
      newValues = currentValues.filter(v => v !== optionValue);
    }

    onFilterChange(filterId, newValues);
  };

  const removeFilter = (filterId: string, optionValue?: string) => {
    const filter = filters.find(f => f.id === filterId);
    if (!filter) return;

    if (filter.type === 'multiselect' && optionValue) {
      const currentValues = Array.isArray(filter.value) ? filter.value : [];
      const newValues = currentValues.filter(v => v !== optionValue);
      onFilterChange(filterId, newValues);
    } else {
      onFilterChange(filterId, filter.type === 'multiselect' ? [] : '');
    }
  };

  const getActiveFilterBadges = () => {
    const badges: Array<{ filterId: string; label: string; value?: string }> =
      [];

    filters.forEach(filter => {
      if (filter.type === 'multiselect' && Array.isArray(filter.value)) {
        filter.value.forEach(value => {
          const option = filter.options.find(opt => opt.value === value);
          if (option) {
            badges.push({
              filterId: filter.id,
              label: `${filter.label}: ${option.label}`,
              value,
            });
          }
        });
      } else if (filter.value && filter.value !== '') {
        const option = filter.options.find(opt => opt.value === filter.value);
        if (option) {
          badges.push({
            filterId: filter.id,
            label: `${filter.label}: ${option.label}`,
          });
        }
      }
    });

    return badges;
  };

  const activeFilterBadges = getActiveFilterBadges();

  if (compact) {
    return (
      <div className={cn('flex items-center gap-2', className)}>
        <Popover open={isFiltersOpen} onOpenChange={setIsFiltersOpen}>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="gap-2">
              <Filter className="h-4 w-4" />
              Filters
              {showFilterCount && activeFiltersCount > 0 && (
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">
                  {activeFiltersCount}
                </Badge>
              )}
              <ChevronDown className="h-4 w-4" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-80 p-4" align="start">
            <div className="space-y-4">
              {filters.map(filter => (
                <div key={filter.id} className="space-y-2">
                  <Label className="text-sm font-medium">{filter.label}</Label>
                  {filter.type === 'select' && (
                    <Select
                      value={(filter.value as string) || ''}
                      onValueChange={value =>
                        handleFilterChange(filter.id, value)
                      }
                    >
                      <SelectTrigger className="w-full">
                        <SelectValue
                          placeholder={filter.placeholder || 'Select...'}
                        />
                      </SelectTrigger>
                      <SelectContent>
                        {filter.options.map(option => (
                          <SelectItem key={option.value} value={option.value}>
                            <div className="flex w-full items-center justify-between">
                              <span>{option.label}</span>
                              {option.count && (
                                <span className="ml-2 text-xs text-gray-500">
                                  ({option.count})
                                </span>
                              )}
                            </div>
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  )}
                  {filter.type === 'multiselect' && (
                    <div className="max-h-40 space-y-2 overflow-y-auto">
                      {filter.options.map(option => (
                        <div
                          key={option.value}
                          className="flex items-center space-x-2"
                        >
                          <Checkbox
                            id={`${filter.id}-${option.value}`}
                            checked={
                              Array.isArray(filter.value) &&
                              filter.value.includes(option.value)
                            }
                            onCheckedChange={checked =>
                              handleMultiSelectChange(
                                filter.id,
                                option.value,
                                checked as boolean
                              )
                            }
                          />
                          <Label
                            htmlFor={`${filter.id}-${option.value}`}
                            className="flex-1 cursor-pointer text-sm"
                          >
                            <div className="flex items-center justify-between">
                              <span>{option.label}</span>
                              {option.count && (
                                <span className="text-xs text-gray-500">
                                  ({option.count})
                                </span>
                              )}
                            </div>
                          </Label>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}

              {activeFiltersCount > 0 && (
                <>
                  <Separator />
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={onClearFilters}
                    className="w-full"
                  >
                    Clear All Filters
                  </Button>
                </>
              )}
            </div>
          </PopoverContent>
        </Popover>

        <Select value={sortBy} onValueChange={onSortChange}>
          <SelectTrigger className="w-40">
            <SelectValue placeholder="Sort by..." />
          </SelectTrigger>
          <SelectContent>
            {sortOptions.map(option => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    );
  }

  return (
    <div className={cn('space-y-4', className)}>
      {/* Filter Controls */}
      <div className="flex flex-wrap items-center gap-4">
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-gray-500" />
          <span className="text-sm font-medium text-gray-700">Filters:</span>
        </div>

        {filters.map(filter => (
          <div key={filter.id} className="min-w-0">
            {filter.type === 'select' && (
              <Select
                value={(filter.value as string) || ''}
                onValueChange={value => handleFilterChange(filter.id, value)}
              >
                <SelectTrigger className="w-40">
                  <SelectValue
                    placeholder={filter.placeholder || filter.label}
                  />
                </SelectTrigger>
                <SelectContent>
                  {filter.options.map(option => (
                    <SelectItem key={option.value} value={option.value}>
                      <div className="flex w-full items-center justify-between">
                        <span>{option.label}</span>
                        {option.count && (
                          <span className="ml-2 text-xs text-gray-500">
                            ({option.count})
                          </span>
                        )}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            {filter.type === 'multiselect' && (
              <Popover>
                <PopoverTrigger asChild>
                  <Button variant="outline" className="w-40 justify-between">
                    <span className="truncate">
                      {Array.isArray(filter.value) && filter.value.length > 0
                        ? `${filter.label} (${filter.value.length})`
                        : filter.label}
                    </span>
                    <ChevronDown className="h-4 w-4 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-60 p-4">
                  <div className="max-h-60 space-y-2 overflow-y-auto">
                    {filter.options.map(option => (
                      <div
                        key={option.value}
                        className="flex items-center space-x-2"
                      >
                        <Checkbox
                          id={`${filter.id}-${option.value}`}
                          checked={
                            Array.isArray(filter.value) &&
                            filter.value.includes(option.value)
                          }
                          onCheckedChange={checked =>
                            handleMultiSelectChange(
                              filter.id,
                              option.value,
                              checked as boolean
                            )
                          }
                        />
                        <Label
                          htmlFor={`${filter.id}-${option.value}`}
                          className="flex-1 cursor-pointer text-sm"
                        >
                          <div className="flex items-center justify-between">
                            <span>{option.label}</span>
                            {option.count && (
                              <span className="text-xs text-gray-500">
                                ({option.count})
                              </span>
                            )}
                          </div>
                        </Label>
                      </div>
                    ))}
                  </div>
                </PopoverContent>
              </Popover>
            )}
          </div>
        ))}

        <div className="flex items-center gap-2">
          <span className="text-sm text-gray-500">Sort by:</span>
          <Select value={sortBy} onValueChange={onSortChange}>
            <SelectTrigger className="w-40">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {sortOptions.map(option => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {activeFiltersCount > 0 && (
          <Button variant="outline" size="sm" onClick={onClearFilters}>
            Clear All
          </Button>
        )}
      </div>

      {/* Active Filter Badges */}
      {activeFilterBadges.length > 0 && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm text-gray-500">Active filters:</span>
          {activeFilterBadges.map((badge, index) => (
            <Badge
              key={`${badge.filterId}-${badge.value || 'single'}-${index}`}
              variant="secondary"
              className="gap-1"
            >
              {badge.label}
              <button
                type="button"
                onClick={() => removeFilter(badge.filterId, badge.value)}
                className="ml-1 rounded-full p-0.5 hover:bg-gray-300"
              >
                <X className="h-3 w-3" />
              </button>
            </Badge>
          ))}
        </div>
      )}
    </div>
  );
}

