'use client';

import { motion, Variants } from 'framer-motion';
import { Coffee, Globe, Award, ArrowRight, Play, Pause } from 'lucide-react';
import Link from 'next/link';
import { useState, useRef, useEffect } from 'react';

import { ServerButton } from '@/presentation/components/ui/server-button';

interface ServerHeroSectionProps {
  title: string;
  subtitle: string;
  ctaText?: string;
  ctaSecondaryText?: string;
  ctaHref?: string;
  ctaSecondaryHref?: string;
  videoSrc?: string;
  videoPoster?: string;
  showVideoControls?: boolean;
}

// Animation variants for staggered entrance
const containerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.2,
      delayChildren: 0.1,
    },
  },
};

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 30 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.6,
      ease: 'easeOut',
    },
  },
};

const floatingVariants: Variants = {
  animate: {
    y: [-10, 10, -10],
    rotate: [0, 5, -5, 0],
    transition: {
      duration: 4,
      repeat: Infinity,
      ease: 'easeInOut',
    },
  },
};

const coffeeBeamVariants: Variants = {
  animate: {
    scale: [1, 1.1, 1],
    opacity: [0.3, 0.6, 0.3],
    transition: {
      duration: 3,
      repeat: Infinity,
      ease: 'easeInOut',
    },
  },
};

export function ServerHeroSection({
  title,
  subtitle,
  ctaText = 'Request a Quote',
  ctaSecondaryText = 'Explore Products',
  ctaHref = '/quote',
  ctaSecondaryHref = '/products',
  videoSrc,
  videoPoster = '/images/hero-poster.jpg',
  showVideoControls = true,
}: ServerHeroSectionProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isVideoLoaded, setIsVideoLoaded] = useState(false);
  const [isMounted, setIsMounted] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  // Handle client-side mounting
  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    const video = videoRef.current;
    if (isMounted && video && videoSrc) {
      video.addEventListener('loadeddata', () => setIsVideoLoaded(true));
      video.addEventListener('ended', () => setIsPlaying(false));

      // Auto-play with error handling (client-side only)
      const playPromise = video.play();
      if (playPromise !== undefined) {
        playPromise
          .then(() => {
            setIsPlaying(true);
          })
          .catch(() => {
            // Auto-play was prevented, show play button
            setIsPlaying(false);
          });
      }
    }
  }, [videoSrc, isMounted]);

  const toggleVideo = () => {
    const video = videoRef.current;
    if (video) {
      if (isPlaying) {
        video.pause();
        setIsPlaying(false);
      } else {
        video
          .play()
          .then(() => {
            setIsPlaying(true);
          })
          .catch(() => {
            setIsPlaying(false);
          });
      }
    }
  };

  return (
    <motion.section
      data-testid="hero-section"
      className="relative min-h-[90vh] overflow-hidden bg-gradient-to-br from-forest-900 via-forest-800 to-forest-900"
      initial="hidden"
      animate="visible"
      variants={containerVariants}
    >
      {/* Video Background */}
      {isMounted && videoSrc && (
        <motion.div
          className="absolute inset-0 z-0"
          initial={{ opacity: 0 }}
          animate={{ opacity: isVideoLoaded ? 1 : 0 }}
          transition={{ duration: 1 }}
        >
          <video
            ref={videoRef}
            className="h-full w-full object-cover"
            poster={videoPoster}
            muted
            loop
            playsInline
            preload="metadata"
            aria-label="Coffee farm processing and bean preparation background video"
            title="Coffee farm processing and bean preparation"
          >
            <source src={videoSrc} type="video/mp4" />
            <track
              kind="descriptions"
              src="/videos/coffee-farm-processing-descriptions.vtt"
              label="Video descriptions"
            />
            Your browser does not support the video tag.
          </video>

          {/* Video Controls */}
          {isMounted && videoSrc && showVideoControls && (
            <motion.button
              onClick={toggleVideo}
              className="absolute bottom-6 right-6 z-30 flex h-12 w-12 items-center justify-center rounded-full bg-black/50 text-white backdrop-blur-sm transition-all duration-300 hover:bg-black/70"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: 1, duration: 0.3 }}
            >
              {isPlaying ? (
                <Pause className="h-5 w-5" />
              ) : (
                <Play className="ml-0.5 h-5 w-5" />
              )}
            </motion.button>
          )}
        </motion.div>
      )}

      {/* Background Overlay - Enhanced for video */}
