                  <Globe className="h-5 w-5 text-emerald-300" />
                </motion.div>
                <motion.div
                  className="flex h-10 w-24 items-center justify-center rounded border border-forest-200/30 bg-gradient-to-r from-forest-200/20 to-emerald-200/20 shadow-sm"
