                className="relative mx-auto h-80 w-80"
                variants={floatingVariants}
                animate="animate"
              >
                <motion.div
                  className="absolute inset-0 rounded-full bg-gradient-to-br from-gold-400/30 to-coffee-600/30 blur-3xl"
                  animate={{
                    scale: [1, 1.2, 1],
                    opacity: [0.3, 0.5, 0.3],
