// Helper function to map region string to CoffeeOrigin type
const mapRegionToOrigin = (region: string): CoffeeOrigin => {
  const regionLower = region.toLowerCase();

  // Map common region names to CoffeeOrigin values
  const regionMap: Record<string, CoffeeOrigin> = {
    vietnam: 'vietnam',
    'viet nam': 'vietnam',
    brazil: 'brazil',
    colombia: 'colombia',
    ethiopia: 'ethiopia',
    guatemala: 'guatemala',
    honduras: 'honduras',
    peru: 'peru',
    indonesia: 'indonesia',
    india: 'india',
    'costa rica': 'costa-rica',
    nicaragua: 'nicaragua',
    ecuador: 'ecuador',
    mexico: 'mexico',
    panama: 'panama',
    jamaica: 'jamaica',
    kenya: 'kenya',
  };

  return regionMap[regionLower] || 'vietnam'; // Default to vietnam if not found
};

interface AdvancedProductComparisonProps {
  products: Product[];
  isOpen: boolean;
  onClose: () => void;
  onRemoveProduct: (productId: string) => void;
  onRequestQuote: (productIds: string[], analysisData?: BulkAnalysis) => void;
  locale: string;
}

interface BulkAnalysis {
  totalQuantity: number;
  totalValue: number;
  averagePrice: number;
  potentialSavings: number;
  recommendedMix: { productId: string; percentage: number; quantity: number }[];
  riskAssessment: 'low' | 'medium' | 'high';
  qualityScore: number;
}

interface ExportData {
  products: Product[];
  analysis: BulkAnalysis | null;
  timestamp: string;
  format: 'csv' | 'pdf' | 'excel';
}

interface ComparisonRow {
  label: string;
  key: string;
  render: (product: Product) => ReactNode;
  category:
    | 'basic'
    | 'specifications'
    | 'pricing'
    | 'availability'
    | 'certifications'
    | 'business';
  importance: 'high' | 'medium' | 'low';
  tooltip?: string;
}

export function AdvancedProductComparison({
  products,
  isOpen,
  onClose,
  onRemoveProduct,
  onRequestQuote,
  locale: _locale,
}: AdvancedProductComparisonProps) {
  const _t = useTranslations('catalog.comparison');
  const [selectedProducts, setSelectedProducts] = useState<Set<string>>(
    new Set(products.map(p => p.id))
  );
  const [bulkQuantity, setBulkQuantity] = useState<number>(1000);
  const [_targetBudget, _setTargetBudget] = useState<number>(50000);
  const [activeTab, setActiveTab] = useState<string>('comparison');
  const [sortBy, setSortBy] = useState<string>('price');
  const [filterBy, setFilterBy] = useState<string>('all');

  // Advanced B2B Analysis
  const bulkAnalysis = useMemo((): BulkAnalysis => {
    const selectedProductsArray = products.filter(p =>
      selectedProducts.has(p.id)
    );
    if (selectedProductsArray.length === 0) {
      return {
        totalQuantity: 0,
        totalValue: 0,
        averagePrice: 0,
        potentialSavings: 0,
        recommendedMix: [],
        riskAssessment: 'low',
        qualityScore: 0,
      };
    }

    const totalValue = selectedProductsArray.reduce((sum, product) => {
      const quantity = bulkQuantity / selectedProductsArray.length;
      const bulkPrice = calculateBulkPrice(product, quantity);
      return sum + bulkPrice * quantity;
    }, 0);

    const qualityScore =
      selectedProductsArray.reduce((sum, product) => {
        let score = 0;
        if (product.grade === 'grade-1') score += 15;
        if (
          product.specifications?.cuppingScore &&
          product.specifications.cuppingScore >= 85
        )
          score += 10;
        if (product.certifications && product.certifications.length > 0)
          score += 5;
        return sum + score;
      }, 0) / selectedProductsArray.length;

    const averagePrice = totalValue / bulkQuantity;
    const standardPrice =
      selectedProductsArray.reduce(
        (sum, product) => sum + product.pricing.basePrice,
        0
      ) / selectedProductsArray.length;
    const potentialSavings = (standardPrice - averagePrice) * bulkQuantity;

    // Remove duplicate quality score calculation since it's already calculated above

    // Risk assessment
    const riskFactors = selectedProductsArray.reduce((factors, product) => {
      if (!product.availability.inStock) factors++;
      if (product.availability.leadTime > 30) factors++;
      if (product.specifications.defectRate > 5) factors++;
      return factors;
    }, 0);

    const riskAssessment: 'low' | 'medium' | 'high' =
      riskFactors === 0 ? 'low' : riskFactors <= 2 ? 'medium' : 'high';

    // Recommended mix based on quality and price optimization
    const recommendedMix = selectedProductsArray.map(product => {
      const qualityWeight = (product.specifications.cuppingScore || 70) / 100;
      const priceWeight =
        1 -
        product.pricing.basePrice /
          Math.max(...selectedProductsArray.map(p => p.pricing.basePrice));
      const score = qualityWeight * 0.6 + priceWeight * 0.4;
      return {
        productId: product.id,
        percentage: Math.round(
          (score /
            selectedProductsArray.reduce((sum, p) => {
              const qw = (p.specifications.cuppingScore || 70) / 100;
              const pw =
                1 -
                p.pricing.basePrice /
                  Math.max(
                    ...selectedProductsArray.map(pr => pr.pricing.basePrice)
                  );
              return sum + (qw * 0.6 + pw * 0.4);
            }, 0)) *
            100
        ),
        quantity: Math.round(
          (score /
            selectedProductsArray.reduce((sum, p) => {
              const qw = (p.specifications.cuppingScore || 70) / 100;
              const pw =
                1 -
                p.pricing.basePrice /
                  Math.max(
                    ...selectedProductsArray.map(pr => pr.pricing.basePrice)
                  );
              return sum + (qw * 0.6 + pw * 0.4);
            }, 0)) *
            bulkQuantity
        ),
      };
    });

    return {
      totalQuantity: bulkQuantity,
      totalValue,
      averagePrice,
      potentialSavings,
      recommendedMix,
      riskAssessment,
      qualityScore,
    };
  }, [products, selectedProducts, bulkQuantity]);

  const calculateBulkPrice = (product: Product, quantity: number): number => {
    let discount = 0;
    if (quantity >= 5000) discount = 0.15;
    else if (quantity >= 2000) discount = 0.1;
    else if (quantity >= 1000) discount = 0.05;
    else if (quantity >= 500) discount = 0.025;

    return product.pricing.basePrice * (1 - discount);
  };

  const comparisonRows: ComparisonRow[] = [
    // Basic Information
    {
      label: 'Product',
      key: 'name',
      category: 'basic',
      importance: 'high',
      render: product => (
        <div className="space-y-2">
          <div className="relative mx-auto h-20 w-20">
            <CardImage
              src={
                product.images.find(img => img.isPrimary)?.url ||
                product.images[0]?.url ||
                ''
              }
              alt={product.name}
              className="rounded-lg object-cover"
              fill
            />
          </div>
          <div className="text-center">
            <h4 className="text-sm font-semibold">{product.name}</h4>
            <p className="text-xs text-muted-foreground">{product.sku}</p>
          </div>
          <div className="flex items-center justify-center gap-1">
            <OriginFlag
              origin={mapRegionToOrigin(product.origin?.region || 'vietnam')}
            />
            <span className="text-xs text-muted-foreground">
              {product.origin?.province || 'Unknown'}
            </span>
          </div>
        </div>
      ),
    },
    {
      label: 'Type & Grade',
      key: 'typeGrade',
      category: 'basic',
      importance: 'high',
      render: product => (
        <div className="space-y-2">
          <Badge variant="secondary">{product.type}</Badge>
          <div className="flex items-center gap-2">
            <CoffeeGradeIndicator grade={product.grade} />
            {product.grade === 'grade-1' && (
              <Badge variant="secondary" className="text-xs">
                Premium Grade
              </Badge>
            )}
          </div>
        </div>
      ),
    },
    {
      label: 'Origin & Processing',
      key: 'originProcessing',
      category: 'basic',
      importance: 'high',
      render: product => (
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <OriginFlag
              origin={mapRegionToOrigin(product.origin?.region || 'Vietnam')}
            />
            <span className="text-sm font-medium">
              {product.origin?.region || 'Vietnam'}
            </span>
          </div>
          <ProcessingMethodBadge method={product.processingMethod} />
          <p className="text-xs text-muted-foreground">
            {product.origin.altitude}m
          </p>
        </div>
      ),
    },

    // Business Metrics
    {
      label: 'Base Price',
      key: 'basePrice',
      category: 'business',
      importance: 'high',
      tooltip: 'Price per kg for standard quantities',
      render: product => (
        <div className="text-center">
          <span className="text-lg font-bold text-green-600">
            ${product.pricing.basePrice.toFixed(2)}
          </span>
          <p className="text-xs text-muted-foreground">
            per {product.pricing.unit}
          </p>
        </div>
      ),
    },
    {
      label: 'Bulk Price (1000kg)',
      key: 'bulkPrice',
      category: 'business',
      importance: 'high',
      tooltip: 'Discounted price for 1000kg orders',
      render: product => {
        const bulkPrice = calculateBulkPrice(product, 1000);
        const savings =
          ((product.pricing.basePrice - bulkPrice) /
            product.pricing.basePrice) *
          100;
        return (
          <div className="text-center">
            <span className="text-lg font-bold text-blue-600">
              ${bulkPrice.toFixed(2)}
            </span>
            <p className="text-xs text-green-600">
              -{savings.toFixed(1)}% savings
            </p>
          </div>
        );
      },
    },
    {
      label: 'ROI Score',
      key: 'roiScore',
      category: 'business',
      importance: 'medium',
      tooltip: 'Return on Investment score based on quality vs price',
      render: product => {
        const qualityScore = product.specifications.cuppingScore || 70;
        const priceScore = 100 - (product.pricing.basePrice / 10) * 10; // Normalize price to 0-100
        const roiScore = Math.round(qualityScore * 0.6 + priceScore * 0.4);
        return (
          <div className="text-center">
            <div className="flex items-center justify-center gap-1">
              <Star className="h-4 w-4 text-amber-500" />
              <span className="font-bold text-amber-600">{roiScore}</span>
            </div>
            <p className="text-xs text-muted-foreground">/ 100</p>
          </div>
        );
      },
    },

    // Technical Specifications
    {
      label: 'Quality Metrics',
      key: 'qualityMetrics',
      category: 'specifications',
      importance: 'high',
      render: product => (
        <div className="space-y-1 text-sm">
          <div className="flex justify-between">
            <span>Moisture:</span>
            <span className="font-medium">
              {product.specifications.moisture}%
            </span>
          </div>
          <div className="flex justify-between">
            <span>Defects:</span>
            <span className="font-medium">
              {product.specifications.defectRate}%
            </span>
          </div>
          <div className="flex justify-between">
            <span>Screen:</span>
            <span className="font-medium">
              {product.specifications.screenSize}
            </span>
          </div>
        </div>
      ),
    },
    {
      label: 'Cupping Score',
      key: 'cuppingScore',
      category: 'specifications',
      importance: 'high',
      render: product => (
        <div className="text-center">
          {product.specifications.cuppingScore ? (
            <div className="space-y-1">
              <span className="text-lg font-bold text-amber-600">
                {product.specifications.cuppingScore}
              </span>
              <p className="text-xs text-muted-foreground">/ 100</p>
              <Badge
                variant={
                  product.specifications.cuppingScore >= 85
                    ? 'default'
                    : 'secondary'
                }
              >
                {product.specifications.cuppingScore >= 85
                  ? 'Specialty'
                  : 'Commercial'}
              </Badge>
            </div>
          ) : (
            <span className="text-sm text-muted-foreground">N/A</span>
          )}
        </div>
      ),
    },

    // Availability & Logistics
    {
      label: 'Availability',
      key: 'availability',
      category: 'availability',
      importance: 'high',
      render: product => (
        <div className="space-y-2">
          <Badge
            variant={product.availability.inStock ? 'default' : 'destructive'}
          >
            {product.availability.inStock ? 'In Stock' : 'Out of Stock'}
          </Badge>
          {product.availability.inStock && (
            <div className="text-xs text-muted-foreground">
              <div className="flex items-center gap-1">
                <Package className="h-3 w-3" />
                <span>
                  {product.availability.stockQuantity.toLocaleString()} kg
                </span>
              </div>
              <div className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                <span>{product.availability.leadTime} days</span>
              </div>
            </div>
          )}
        </div>
      ),
    },
    {
      label: 'Harvest Season',
      key: 'harvestSeason',
      category: 'availability',
      importance: 'medium',
      render: product => (
        <span className="text-sm">{product.availability.harvestSeason}</span>
      ),
    },

    // Certifications
    {
      label: 'Certifications',
      key: 'certifications',
      category: 'certifications',
      importance: 'medium',
      render: product => (
        <div className="flex flex-wrap gap-1">
          {product.certifications && product.certifications.length > 0 ? (
            product.certifications.map(cert => (
              <CertificationBadge key={cert} certification={cert} />
            ))
          ) : (
            <span className="text-sm text-muted-foreground">None</span>
          )}
        </div>
      ),
    },
  ];

  const filteredRows = comparisonRows.filter(row => {
    if (filterBy === 'all') return true;
    if (filterBy === 'high-importance') return row.importance === 'high';
    return row.category === filterBy;
  });

  const sortedProducts = [...products].sort((a, b) => {
    switch (sortBy) {
      case 'price':
        return a.pricing.basePrice - b.pricing.basePrice;
      case 'quality':
        return (
          (b.specifications.cuppingScore || 0) -
          (a.specifications.cuppingScore || 0)
        );
      case 'availability':
        return (
          (b.availability.inStock ? 1 : 0) - (a.availability.inStock ? 1 : 0)
        );
      default:
        return 0;
    }
  });

  const groupedRows = filteredRows.reduce(
    (acc, row) => {
      if (!acc[row.category]) {
        acc[row.category] = [];
      }
      acc[row.category]!.push(row);
      return acc;
    },
    {} as Record<string, ComparisonRow[]>
  );

  const categoryLabels = {
    basic: 'Basic Information',
    business: 'Business Metrics',
    specifications: 'Technical Specifications',
    pricing: 'Pricing Analysis',
    availability: 'Availability & Logistics',
    certifications: 'Certifications & Standards',
  };

  const handleToggleProduct = (productId: string) => {
    const newSelected = new Set(selectedProducts);
    if (newSelected.has(productId)) {
      newSelected.delete(productId);
    } else {
      newSelected.add(productId);
    }
    setSelectedProducts(newSelected);
  };

  const handleRequestQuote = () => {
    onRequestQuote(Array.from(selectedProducts), bulkAnalysis);
  };

  const handleExportComparison = (format: 'csv' | 'pdf' | 'excel') => {
    // Enhanced export with business analysis
    const exportData = {
      products: sortedProducts.filter(p => selectedProducts.has(p.id)),
      analysis: bulkAnalysis,
      timestamp: new Date().toISOString(),
      format,
    };

    if (format === 'csv') {
      const csvContent = generateAdvancedCSV(exportData);
      const blob = new Blob([csvContent], { type: 'text/csv' });
      downloadFile(blob, {
        filename: `coffee-comparison-${new Date().toISOString().split('T')[0]}.csv`,
        mimeType: 'text/csv'
      });
    }
    // PDF and Excel exports would be implemented here
  };



  const generateAdvancedCSV = (_data: ExportData): string => {
    // Implementation would generate comprehensive CSV with business analysis
    return 'Advanced CSV content with business metrics...';
  };

  if (products.length === 0) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-h-[95vh] max-w-[95vw] overflow-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Scale className="h-5 w-5" />
              <span>
                Advanced Product Comparison ({products.length} products)
              </span>
            </div>
            <div className="flex gap-2">
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger className="w-32">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="price">Sort by Price</SelectItem>
                  <SelectItem value="quality">Sort by Quality</SelectItem>
                  <SelectItem value="availability">Sort by Stock</SelectItem>
                </SelectContent>
              </Select>
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleExportComparison('csv')}
              >
                <Download className="mr-2 h-4 w-4" />
                Export
              </Button>
              <Button
                onClick={handleRequestQuote}
                disabled={selectedProducts.size === 0}
              >
                <ShoppingCart className="mr-2 h-4 w-4" />
                Quote ({selectedProducts.size})
              </Button>
            </div>
          </DialogTitle>
        </DialogHeader>

        <Tabs
          value={activeTab}
          onValueChange={setActiveTab}
          className="flex-1 overflow-hidden"
        >
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="comparison">Detailed Comparison</TabsTrigger>
            <TabsTrigger value="analysis">Business Analysis</TabsTrigger>
            <TabsTrigger value="recommendations">
              AI Recommendations
            </TabsTrigger>
          </TabsList>

          <TabsContent value="comparison" className="flex-1 overflow-hidden">
            <div className="space-y-4">
              <div className="flex items-center gap-4">
                <Select value={filterBy} onValueChange={setFilterBy}>
                  <SelectTrigger className="w-48">
                    <SelectValue placeholder="Filter categories" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Categories</SelectItem>
                    <SelectItem value="high-importance">
                      High Priority Only
                    </SelectItem>
                    <SelectItem value="business">Business Metrics</SelectItem>
                    <SelectItem value="specifications">
                      Technical Specs
                    </SelectItem>
                    <SelectItem value="availability">Availability</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="max-h-[60vh] flex-1 overflow-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="sticky left-0 z-10 w-48 bg-background">
                        Specification
                      </TableHead>
                      {sortedProducts.map(product => (
                        <TableHead
                          key={product.id}
                          className="min-w-48 text-center"
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2">
                              <input
                                type="checkbox"
                                checked={selectedProducts.has(product.id)}
                                onChange={() => handleToggleProduct(product.id)}
                                className="rounded"
                              />
                              <span className="text-xs">Select</span>
                            </div>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => onRemoveProduct(product.id)}
                              className="h-6 w-6 p-0"
                            >
                              <X className="h-3 w-3" />
                            </Button>
                          </div>
                        </TableHead>
                      ))}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {Object.entries(groupedRows).map(([category, rows]) => (
                      <Fragment key={category}>
                        <TableRow className="bg-muted/50">
                          <TableCell
                            colSpan={sortedProducts.length + 1}
                            className="sticky left-0 z-10 bg-muted/50 text-sm font-semibold"
                          >
                            {
                              categoryLabels[
                                category as keyof typeof categoryLabels
                              ]
                            }
                          </TableCell>
                        </TableRow>
                        {rows.map(row => (
                          <TableRow key={row.key}>
                            <TableCell className="sticky left-0 z-10 bg-background font-medium">
                              <TooltipProvider>
                                <Tooltip>
                                  <TooltipTrigger className="flex items-center gap-1">
                                    {row.label}
                                    {row.tooltip && (
                                      <Info className="h-3 w-3 text-muted-foreground" />
                                    )}
                                  </TooltipTrigger>
                                  {row.tooltip && (
                                    <TooltipContent>
                                      <p>{row.tooltip}</p>
                                    </TooltipContent>
                                  )}
                                </Tooltip>
                              </TooltipProvider>
                            </TableCell>
                            {sortedProducts.map(product => (
                              <TableCell
                                key={product.id}
                                className="text-center"
                              >
                                {row.render(product)}
                              </TableCell>
                            ))}
                          </TableRow>
                        ))}
                      </Fragment>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="analysis" className="space-y-6">
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <Package className="h-4 w-4" />
                    Total Quantity
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {bulkAnalysis.totalQuantity.toLocaleString()} kg
                  </div>
                  <div className="mt-2 flex items-center gap-2">
                    <Label htmlFor="quantity">Target Quantity:</Label>
                    <Input
                      id="quantity"
                      type="number"
                      value={bulkQuantity}
                      onChange={e => setBulkQuantity(Number(e.target.value))}
                      className="w-24"
                    />
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <DollarSign className="h-4 w-4" />
                    Total Value
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-green-600">
                    ${bulkAnalysis.totalValue.toLocaleString()}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Avg: ${bulkAnalysis.averagePrice.toFixed(2)}/kg
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <TrendingUp className="h-4 w-4" />
                    Potential Savings
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-blue-600">
                    ${bulkAnalysis.potentialSavings.toLocaleString()}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    vs standard pricing
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <Target className="h-4 w-4" />
                    Quality Score
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-amber-600">
                    {bulkAnalysis.qualityScore.toFixed(1)}
                  </div>
                  <Badge
                    variant={
                      bulkAnalysis.riskAssessment === 'low'
                        ? 'default'
                        : bulkAnalysis.riskAssessment === 'medium'
                          ? 'secondary'
                          : 'destructive'
                    }
                  >
                    {bulkAnalysis.riskAssessment} risk
                  </Badge>
                </CardContent>
              </Card>
            </div>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <BarChart3 className="h-5 w-5" />
                  Recommended Product Mix
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {bulkAnalysis.recommendedMix.map(mix => {
                    const product = products.find(p => p.id === mix.productId);
                    if (!product) return null;

                    return (
                      <div
                        key={mix.productId}
                        className="flex items-center justify-between rounded-lg border p-3"
                      >
                        <div className="flex items-center gap-3">
                          <div className="relative h-12 w-12">
                            <CardImage
                              src={
                                product.images.find(img => img.isPrimary)
                                  ?.url ||
                                product.images[0]?.url ||
                                ''
                              }
                              alt={product.name}
                              className="rounded object-cover"
                              fill
                            />
                          </div>
                          <div>
                            <h4 className="font-medium">{product.name}</h4>
                            <p className="text-sm text-muted-foreground">
                              {product.sku}
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className="text-lg font-bold">
                            {mix.percentage}%
                          </div>
                          <div className="text-sm text-muted-foreground">
                            {mix.quantity.toLocaleString()} kg
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="recommendations" className="space-y-6">
            <div className="grid gap-4">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <CheckCircle className="h-5 w-5 text-green-600" />
                    AI-Powered Recommendations
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="rounded-lg border border-green-200 bg-green-50 p-4">
                    <h4 className="mb-2 font-semibold text-green-800">
                      Optimal Purchase Strategy
                    </h4>
                    <p className="text-sm text-green-700">
                      Based on your selection, we recommend a 60/40 split
                      between premium and commercial grades to optimize both
                      quality and cost-effectiveness for your target market.
                    </p>
                  </div>

                  <div className="rounded-lg border border-blue-200 bg-blue-50 p-4">
                    <h4 className="mb-2 font-semibold text-blue-800">
                      Seasonal Timing
                    </h4>
                    <p className="text-sm text-blue-700">
                      Consider placing orders for Vietnamese Robusta between
                      October-December for best pricing and freshness, aligning
                      with harvest seasons.
                    </p>
                  </div>

                  {bulkAnalysis.riskAssessment !== 'low' && (
                    <div className="rounded-lg border border-amber-200 bg-amber-50 p-4">
                      <h4 className="mb-2 flex items-center gap-2 font-semibold text-amber-800">
                        <AlertTriangle className="h-4 w-4" />
                        Risk Mitigation
                      </h4>
                      <p className="text-sm text-amber-700">
                        Some selected products have higher lead times or limited
                        stock. Consider diversifying your supplier base or
                        adjusting quantities to reduce supply chain risks.
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import {
  ShoppingCart,
  Scale,
  TrendingUp,
  Package,
  Clock,
  Star,
  Plus,
  Minus,
  Eye,
  Download,
  CheckCircle,
  Users,
} from 'lucide-react';
import Link from 'next/link';
import { useState } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/presentation/components/ui/tabs';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/presentation/components/ui/tooltip';
import { CardImage } from '@/shared/components/performance/OptimizedImage';
import { cn } from '@/shared/utils/cn';

interface RelatedProduct {
  id: string;
  name: string;
  shortDescription: string;
  images: Array<{ url: string; alt: string; isPrimary: boolean }>;
  pricing: {
    basePrice: number;
    unit: string;
    minimumOrder: number;
    incoterms: string[];
  };
  grade: string;
  origin: {
    region: string;
    country: string;
  };
  processingMethod: string;
  certifications: string[];
  availability: {
    inStock: boolean;
    leadTime: number;
  };
  isFeatured: boolean;
  specifications: {
    moisture: string;
    screenSize: string;
    defectRate: string;
    cuppingScore?: number;
  };
}

interface BulkOption {
  quantity: number;
  unit: string;
  pricePerUnit: number;
  discount: number;
  leadTime: number;
  packaging: string;
}

interface EnhancedRelatedProductsProps {
  products: RelatedProduct[];
  currentProduct: {
    id: string;
    type: string;
    grade: string;
  };
  locale: string;
  className?: string;
}

const bulkOptions: BulkOption[] = [
  {
    quantity: 1,
    unit: 'MT',
    pricePerUnit: 2850,
    discount: 0,
    leadTime: 14,
    packaging: 'Jute Bags',
  },
  {
    quantity: 5,
    unit: 'MT',
    pricePerUnit: 2750,
    discount: 3.5,
    leadTime: 21,
    packaging: 'Jute Bags',
  },
  {
    quantity: 10,
    unit: 'MT',
    pricePerUnit: 2650,
    discount: 7,
    leadTime: 28,
    packaging: 'Bulk Container',
  },
  {
    quantity: 20,
    unit: 'MT',
    pricePerUnit: 2550,
    discount: 10.5,
    leadTime: 35,
    packaging: 'Bulk Container',
  },
];

const recommendationReasons = {
  'same-type': 'Same coffee type - perfect for consistent blending',
  'same-grade': 'Similar quality grade - maintains your standards',
  'same-origin': 'Same origin region - familiar flavor profile',
  complementary: 'Complementary profile - ideal for custom blends',
  seasonal: 'Seasonal availability - secure your supply chain',
  'premium-upgrade': 'Premium upgrade option - enhance your offerings',
};

export function EnhancedRelatedProducts({
  products,
  currentProduct,
  locale,
  className,
}: EnhancedRelatedProductsProps) {
  const [selectedProducts, setSelectedProducts] = useState<Set<string>>(
    new Set()
  );
  const [bulkQuantities, setBulkQuantities] = useState<Record<string, number>>(
    {}
  );
  const [activeTab, setActiveTab] = useState<
    'recommendations' | 'bulk' | 'comparison'
  >('recommendations');

  const handleProductSelect = (productId: string, selected: boolean) => {
    const newSelected = new Set(selectedProducts);
    if (selected) {
      newSelected.add(productId);
    } else {
      newSelected.delete(productId);
    }
    setSelectedProducts(newSelected);
  };

  const handleQuantityChange = (productId: string, quantity: number) => {
    setBulkQuantities(prev => ({
      ...prev,
      [productId]: Math.max(1, quantity),
    }));
  };

  const getRecommendationReason = (
    product: RelatedProduct
  ): keyof typeof recommendationReasons => {
    if (
      product.grade === currentProduct.grade &&
      product.id !== currentProduct.id
    ) {
      return 'same-grade';
    }
    if (product.origin.region === currentProduct.type) {
      return 'same-origin';
    }
    if (product.isFeatured) {
      return 'premium-upgrade';
    }
    return 'complementary';
  };

  const calculateBulkPrice = (
    basePrice: number,
    quantity: number
  ): BulkOption => {
    const option = bulkOptions.find(opt => quantity >= opt.quantity) ||
      bulkOptions[0] || {
        quantity: 1,
        unit: 'MT',
        pricePerUnit: basePrice,
        discount: 0,
        leadTime: 14,
        packaging: 'Standard',
      };
    return {
      ...option,
      pricePerUnit: basePrice * (1 - option.discount / 100),
    };
  };

  const ProductCard = ({ product }: { product: RelatedProduct }) => {
    const primaryImage =
      product.images.find(img => img.isPrimary) || product.images[0];
    const quantity = bulkQuantities[product.id] || 1;
    const bulkPrice = calculateBulkPrice(product.pricing.basePrice, quantity);
    const reason = getRecommendationReason(product);

    return (
      <Card className="hover:shadow-coffee-glow group relative overflow-hidden border-coffee-200/50 transition-all duration-300 hover:shadow-xl">
        {/* Recommendation Badge */}
        <div className="absolute left-3 top-3 z-10">
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger>
                <Badge
                  variant="secondary"
                  className="border-amber-200 bg-amber-100 text-amber-800"
                >
                  <TrendingUp className="mr-1 h-3 w-3" />
                  Recommended
                </Badge>
              </TooltipTrigger>
              <TooltipContent>
                <p className="text-sm">{recommendationReasons[reason]}</p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>

        {/* Selection Checkbox */}
        <div className="absolute right-3 top-3 z-10">
          <Button
            variant={selectedProducts.has(product.id) ? 'default' : 'outline'}
            size="sm"
            onClick={() =>
              handleProductSelect(product.id, !selectedProducts.has(product.id))
            }
            className="h-8 w-8 p-0"
          >
            {selectedProducts.has(product.id) ? (
              <CheckCircle className="h-4 w-4" />
            ) : (
              <Plus className="h-4 w-4" />
            )}
          </Button>
        </div>

        {/* Product Image */}
        <div className="relative aspect-video bg-coffee-50">
          <CardImage
            src={primaryImage?.url || '/images/coffee-beans-placeholder.jpg'}
            alt={primaryImage?.alt || product.name}
            fill
            className="object-cover transition-transform duration-300 group-hover:scale-105"
            sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
          />

          {/* Availability Badge */}
          <Badge
            variant={product.availability.inStock ? 'default' : 'destructive'}
            className="absolute bottom-3 left-3"
          >
            {product.availability.inStock ? 'In Stock' : 'Out of Stock'}
          </Badge>

          {/* Featured Badge */}
          {product.isFeatured && (
            <Badge className="absolute bottom-3 right-3 bg-gold-500 text-white">
              <Star className="mr-1 h-3 w-3" />
              Featured
            </Badge>
          )}
        </div>

        <CardHeader className="pb-4">
          <CardTitle className="text-lg font-semibold text-coffee-800 transition-colors group-hover:text-coffee-600">
            {product.name}
          </CardTitle>
          <CardDescription className="text-sm text-coffee-600">
            {product.shortDescription}
          </CardDescription>

          {/* Key Specifications */}
          <div className="mt-2 flex flex-wrap gap-2">
            <Badge variant="outline" className="text-xs">
              {product.grade.replace('_', ' ')}
            </Badge>
            <Badge variant="outline" className="text-xs">
              {product.origin.region}
            </Badge>
            <Badge variant="outline" className="text-xs">
              {product.processingMethod}
            </Badge>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Pricing Information */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium text-coffee-700">
                Base Price:
              </span>
              <span className="text-lg font-bold text-coffee-800">
                ${product.pricing.basePrice.toLocaleString()}/
                {product.pricing.unit}
              </span>
            </div>

            {quantity > 1 && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-coffee-600">
                  Bulk Price ({quantity} MT):
                </span>
                <span className="font-semibold text-emerald-600">
                  ${bulkPrice.pricePerUnit.toLocaleString()}/
                  {product.pricing.unit}
                  {bulkPrice.discount > 0 && (
                    <span className="ml-1 text-xs text-emerald-500">
                      (-{bulkPrice.discount}%)
                    </span>
                  )}
                </span>
              </div>
            )}
          </div>

          {/* Quantity Selector */}
          <div className="space-y-2">
            <label className="text-sm font-medium text-coffee-700">
              Quantity (MT):
            </label>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleQuantityChange(product.id, quantity - 1)}
                disabled={quantity <= 1}
                className="h-8 w-8 p-0"
              >
                <Minus className="h-4 w-4" />
              </Button>
              <Select
                value={quantity.toString()}
                onValueChange={value =>
                  handleQuantityChange(product.id, parseInt(value))
                }
              >
                <SelectTrigger className="h-8 w-20">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {[1, 5, 10, 20, 50].map(qty => (
                    <SelectItem key={qty} value={qty.toString()}>
                      {qty}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleQuantityChange(product.id, quantity + 1)}
                className="h-8 w-8 p-0"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* Lead Time & MOQ */}
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="flex items-center gap-1 text-coffee-600">
              <Clock className="h-3 w-3" />
              <span>{product.availability.leadTime} days</span>
            </div>
            <div className="flex items-center gap-1 text-coffee-600">
              <Package className="h-3 w-3" />
              <span>MOQ: {product.pricing.minimumOrder} MT</span>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-2 pt-2">
            <Button variant="outline" size="sm" asChild className="flex-1">
              <Link href={`/${locale}/products/${product.id}`}>
                <Eye className="mr-1 h-4 w-4" />
                View Details
              </Link>
            </Button>
            <Button
              size="sm"
              asChild
              className="flex-1 bg-coffee-600 hover:bg-coffee-700"
            >
              <Link
                href={`/${locale}/quote?product=${product.id}&quantity=${quantity}`}
              >
                <ShoppingCart className="mr-1 h-4 w-4" />
                Quote
              </Link>
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  };

  const BulkOptionsPanel = () => (
    <div className="space-y-6">
      <div className="text-center">
        <h3 className="mb-2 text-xl font-semibold text-coffee-800">
          Bulk Purchase Options
        </h3>
        <p className="text-coffee-600">
          Save more with larger quantities. Perfect for roasters and
          distributors.
        </p>
      </div>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
        {bulkOptions.map((option, _index) => (
          <Card
            key={`bulk-${option.quantity}-${option.unit}`}
            className="border-coffee-200 transition-colors hover:border-coffee-300"
          >
            <CardHeader className="pb-3">
              <CardTitle className="text-lg text-coffee-800">
                {option.quantity} {option.unit}
              </CardTitle>
              {option.discount > 0 && (
                <Badge
                  variant="secondary"
                  className="w-fit bg-emerald-100 text-emerald-800"
                >
                  Save {option.discount}%
                </Badge>
              )}
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="text-2xl font-bold text-coffee-800">
                ${option.pricePerUnit.toLocaleString()}
                <span className="text-sm font-normal text-coffee-600">/MT</span>
              </div>
              <div className="space-y-2 text-sm text-coffee-600">
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4" />
                  <span>{option.leadTime} days delivery</span>
                </div>
                <div className="flex items-center gap-2">
                  <Package className="h-4 w-4" />
                  <span>{option.packaging}</span>
                </div>
              </div>
              <Button className="w-full sm:w-auto" size="sm">
                Select This Option
              </Button>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="rounded-lg bg-coffee-50 p-6">
        <h4 className="mb-3 font-semibold text-coffee-800">
          Bulk Purchase Benefits
        </h4>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          <div className="flex items-start gap-3">
            <CheckCircle className="mt-0.5 h-5 w-5 text-emerald-500" />
            <div>
              <h5 className="font-medium text-coffee-700">Volume Discounts</h5>
              <p className="text-sm text-coffee-600">
                Save up to 10.5% on large orders
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <CheckCircle className="mt-0.5 h-5 w-5 text-emerald-500" />
            <div>
              <h5 className="font-medium text-coffee-700">
                Priority Processing
              </h5>
              <p className="text-sm text-coffee-600">
                Faster handling for bulk orders
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <CheckCircle className="mt-0.5 h-5 w-5 text-emerald-500" />
            <div>
              <h5 className="font-medium text-coffee-700">Flexible Payment</h5>
              <p className="text-sm text-coffee-600">
                Extended payment terms available
              </p>
            </div>
          </div>
          <div className="flex items-start gap-3">
            <CheckCircle className="mt-0.5 h-5 w-5 text-emerald-500" />
            <div>
              <h5 className="font-medium text-coffee-700">Quality Assurance</h5>
              <p className="text-sm text-coffee-600">
                Consistent quality across batches
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const ComparisonPanel = () => (
    <div className="space-y-6">
      <div className="text-center">
        <h3 className="mb-2 text-xl font-semibold text-coffee-800">
          Product Comparison
        </h3>
        <p className="text-coffee-600">
          Compare selected products side by side to make informed decisions.
        </p>
      </div>

      {selectedProducts.size === 0 ? (
        <div className="py-12 text-center">
          <Scale className="mx-auto mb-4 h-16 w-16 text-coffee-300" />
          <h4 className="mb-2 text-lg font-medium text-coffee-700">
            No Products Selected
          </h4>
          <p className="text-coffee-600">
            Select products from the recommendations tab to compare them here.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-coffee-700">
              {selectedProducts.size} product(s) selected
            </span>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setSelectedProducts(new Set())}
            >
              Clear All
            </Button>
          </div>

          <div className="grid grid-cols-1 gap-4 lg:grid-cols-2 xl:grid-cols-3">
            {Array.from(selectedProducts).map(productId => {
              const product = products.find(p => p.id === productId);
              if (!product) return null;

              return (
                <Card key={productId} className="border-coffee-200">
                  <CardHeader className="pb-3">
                    <div className="flex items-start justify-between">
                      <CardTitle className="text-base">
                        {product.name}
                      </CardTitle>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleProductSelect(productId, false)}
                        className="h-6 w-6 p-0"
                      >
                        <Minus className="h-4 w-4" />
                      </Button>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div className="space-y-2 text-sm">
