'use client';

import { Download, FileText, Loader2 } from 'lucide-react';
import { useTranslations } from 'next-intl';
import React from 'react';

import { downloadPDF } from '@/shared/utils/download';

import type {
  CoffeeProduct,
  CoffeeProductEntity,
} from '@/domain/entities/coffee-product.entity';
import type { RFQ, RFQEntity } from '@/domain/entities/rfq.entity';
import { Button } from '@/presentation/components/ui/button';
import { usePDFGeneration } from '@/shared/hooks/use-pdf-generation';
import { cn } from '@/shared/utils';

export type PDFType =
  | 'productSpec'
  | 'rfqDocument'
  | 'marketReport'
  | 'certificate';

interface PDFDownloadButtonProps {
  type: PDFType;
  entityId: string;
  entityData?: CoffeeProduct | RFQ | Record<string, unknown>;
  locale?: string;
  options?: {
    format?: 'A4' | 'Letter' | 'Legal';
    orientation?: 'portrait' | 'landscape';
    quality?: number;
    includeWatermark?: boolean;
    includeHeader?: boolean;
    includeFooter?: boolean;
  };
  variant?: 'default' | 'outline' | 'ghost' | 'link';
  size?: 'sm' | 'default' | 'lg';
  className?: string;
  children?: React.ReactNode;
  showIcon?: boolean;
  disabled?: boolean;
  onSuccess?: (filename: string) => void;
  onError?: (error: Error) => void;
}

export const PDFDownloadButton: React.FC<PDFDownloadButtonProps> = ({
  type,
  entityId,
  entityData,
  locale,
  options = {},
  variant = 'default',
  size = 'default',
  className,
  children,
  showIcon = true,
  disabled = false,
  onSuccess,
  onError,
}) => {
  const t = useTranslations('pdf.buttons');
  const {
    generateProductSpecSheet,
    generateRFQDocument,
    generateFromHTML,
    isGenerating,
    error: _error,
  } = usePDFGeneration();

  const getButtonText = () => {
    if (isGenerating) {
      return t('downloading');
    }

    switch (type) {
      case 'productSpec':
        return children || t('downloadSpec');
      case 'rfqDocument':
        return children || t('downloadRfq');
      case 'marketReport':
        return children || t('downloadReport');
      case 'certificate':
        return children || t('downloadCertificate');
      default:
        return children || t('generatePdf');
    }
  };

  const handleDownload = async () => {
    try {
      switch (type) {
        case 'productSpec':
          if (!entityData) {
            throw new Error(
              'Product data is required for product spec PDF generation'
            );
          }
          await generateProductSpecSheet(
            entityData as unknown as CoffeeProductEntity,
            {
              ...options,
              language: locale || 'en',
            }
          );
          break;
        case 'rfqDocument':
          if (!entityData) {
            throw new Error(
              'RFQ data is required for RFQ document PDF generation'
            );
          }
          await generateRFQDocument(entityData as unknown as RFQEntity, {
            ...options,
            language: locale || 'en',
          });
          break;
        case 'marketReport':
          if (!entityData) {
            throw new Error('Market report data is required');
          }
          // Create a temporary HTML element for market report
          const marketReportElement = document.createElement('div');
          marketReportElement.innerHTML = `
            <div style="padding: 20px; font-family: Arial, sans-serif;">
              <h1>Market Report</h1>
              <p>Generated on: ${new Date().toLocaleDateString()}</p>
              <pre>${JSON.stringify(entityData, null, 2)}</pre>
            </div>
          `;
          document.body.appendChild(marketReportElement);
          try {
            await generateFromHTML(
              marketReportElement,
              `market-report-${new Date().toISOString().split('T')[0]}.pdf`
            );
          } finally {
            document.body.removeChild(marketReportElement);
          }
          break;

        case 'certificate':
          if (!entityData) {
            throw new Error('Certificate data is required');
          }
          // Create a temporary HTML element for certificate
          const certificateElement = document.createElement('div');
          certificateElement.innerHTML = `
            <div style="padding: 20px; font-family: Arial, sans-serif; text-align: center;">
              <h1>Certificate</h1>
              <p>This certifies that the following information is accurate:</p>
              <div style="margin: 20px 0; text-align: left;">
                <pre>${JSON.stringify(entityData, null, 2)}</pre>
              </div>
              <p>Generated on: ${new Date().toLocaleDateString()}</p>
            </div>
          `;
          document.body.appendChild(certificateElement);
          try {
            await generateFromHTML(
              certificateElement,
              `certificate-${new Date().toISOString().split('T')[0]}.pdf`
            );
          } finally {
            document.body.removeChild(certificateElement);
          }
          break;
        default:
          throw new Error(`Unsupported PDF type: ${type}`);
      }

      onSuccess?.(`${type}-${entityId}.pdf`);
    } catch (err) {
      const error =
        err instanceof Error ? err : new Error('Unknown error occurred');
      onError?.(error);
    }
  };

  return (
    <Button
      variant={variant}
      size={size}
      className={cn(
        'relative',
        isGenerating && 'cursor-not-allowed',
        className
      )}
      disabled={disabled || isGenerating}
      onClick={handleDownload}
    >
      {isGenerating ? (
        <>
          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          {getButtonText()}
        </>
      ) : (
        <>
          {showIcon && <Download className="mr-2 h-4 w-4" />}
          {getButtonText()}
        </>
      )}
    </Button>
  );
};

// Specialized components for common use cases
export const ProductSpecDownloadButton: React.FC<
  Omit<PDFDownloadButtonProps, 'type' | 'entityId'> & { productId: string }
> = ({ productId, ...props }) => (
  <PDFDownloadButton type="productSpec" entityId={productId} {...props} />
);

export const RFQDocumentDownloadButton: React.FC<
  Omit<PDFDownloadButtonProps, 'type' | 'entityId'> & { rfqId: string }
> = ({ rfqId, ...props }) => (
  <PDFDownloadButton type="rfqDocument" entityId={rfqId} {...props} />
);

// Batch download component for multiple PDFs
interface BatchPDFDownloadButtonProps {
  items: Array<{
    type: PDFType;
    entityId: string;
    entityData?: CoffeeProduct | RFQ | Record<string, unknown>;
    filename?: string;
  }>;
  locale?: string;
  options?: PDFDownloadButtonProps['options'];
  variant?: PDFDownloadButtonProps['variant'];
  size?: PDFDownloadButtonProps['size'];
  className?: string;
  children?: React.ReactNode;
  onSuccess?: (filenames: string[]) => void;
  onError?: (error: Error) => void;
}

export const BatchPDFDownloadButton: React.FC<BatchPDFDownloadButtonProps> = ({
  items,
  locale,
  options = {},
  variant = 'default',
  size = 'default',
  className,
  children,
  onSuccess,
  onError,
}) => {
  const t = useTranslations('pdf.buttons');
  const tBatch = useTranslations('pdf.batch');
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [progress, setProgress] = React.useState(0);

  const handleBatchDownload = async () => {
    if (items.length === 0) return;

    setIsGenerating(true);
    setProgress(0);

    try {
      const filenames: string[] = [];

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (!item) continue;

        // Generate PDF based on type
        const response = await fetch(`/api/pdf/${item.type}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            [`${item.type === 'productSpec' ? 'productId' : 'rfqId'}`]:
              item.entityId,
            locale,
            options,
          }),
        });

        if (!response.ok) {
          throw new Error(`Failed to generate PDF for ${item.entityId}`);
        }

        const blob = await response.blob();
        const filename =
          item.filename || `${item.type}-${item.entityId}-${Date.now()}.pdf`;

        // Download the file
        downloadPDF(blob, filename);

        filenames.push(filename);
        setProgress(((i + 1) / items.length) * 100);
      }

      onSuccess?.(filenames);
    } catch (err) {
      const error =
        err instanceof Error ? err : new Error('Batch download failed');
      onError?.(error);
    } finally {
      setIsGenerating(false);
      setProgress(0);
    }
  };

  return (
    <Button
      variant={variant}
      size={size}
      className={cn(
        'relative',
        isGenerating && 'cursor-not-allowed',
        className
      )}
      disabled={isGenerating || items.length === 0}
      onClick={handleBatchDownload}
    >
      {isGenerating ? (
        <>
          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          {tBatch('generating.description', { count: items.length })}
          {progress > 0 && (
            <span className="ml-2 text-xs">({Math.round(progress)}%)</span>
          )}
        </>
      ) : (
        <>
          <FileText className="mr-2 h-4 w-4" />
          {children || `${t('generatePdf')} (${items.length})`}
        </>
      )}
    </Button>
  );
};

export default PDFDownloadButton;

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { onCLS, onFCP, onINP, onLCP, onTTFB, type Metric } from 'web-vitals';

import { createScopedLogger } from '@/shared/utils/logger';

const _logger = createScopedLogger('CoreWebVitalsMonitor');

// Core Web Vitals thresholds (Google's recommended values)
const THRESHOLDS = {
  LCP: { good: 2500, needsImprovement: 4000 }, // Largest Contentful Paint
  INP: { good: 200, needsImprovement: 500 }, // Interaction to Next Paint
  CLS: { good: 0.1, needsImprovement: 0.25 }, // Cumulative Layout Shift
  FCP: { good: 1800, needsImprovement: 3000 }, // First Contentful Paint
  TTFB: { good: 800, needsImprovement: 1800 }, // Time to First Byte
};

// Performance rating based on thresholds
type PerformanceRating = 'good' | 'needs-improvement' | 'poor';

interface WebVitalMetric {
  name: string;
  value: number;
  rating: PerformanceRating;
  delta: number;
  id: string;
  navigationType: string;
}

interface CoreWebVitalsData {
  LCP?: WebVitalMetric;
  INP?: WebVitalMetric;
  CLS?: WebVitalMetric;
  FCP?: WebVitalMetric;
  TTFB?: WebVitalMetric;
}

interface CoreWebVitalsMonitorProps {
  enableAnalytics?: boolean;
  enableConsoleLogging?: boolean;
  enableVisualIndicator?: boolean;
  onMetricCapture?: (metric: WebVitalMetric) => void;
  analyticsEndpoint?: string;
}

/**
 * Core Web Vitals Monitor Component
 *
 * Monitors and reports Core Web Vitals metrics including:
 * - LCP (Largest Contentful Paint)
 * - INP (Interaction to Next Paint)
 * - CLS (Cumulative Layout Shift)
 * - FCP (First Contentful Paint)
 * - TTFB (Time to First Byte)
 */
export function CoreWebVitalsMonitor({
  enableAnalytics = true,
  enableConsoleLogging = false,
  enableVisualIndicator = false,
  onMetricCapture,
  analyticsEndpoint = '/api/analytics/web-vitals',
}: CoreWebVitalsMonitorProps) {
  const [metrics, setMetrics] = useState<CoreWebVitalsData>({});
  const [isVisible, setIsVisible] = useState(enableVisualIndicator);
  const sentMetrics = useRef(new Set<string>());

  // Get performance rating based on metric value and thresholds
  const getPerformanceRating = (
    name: string,
    value: number
  ): PerformanceRating => {
    const threshold = THRESHOLDS[name as keyof typeof THRESHOLDS];
    if (!threshold) return 'good';

    if (value <= threshold.good) return 'good';
    if (value <= threshold.needsImprovement) return 'needs-improvement';
    return 'poor';
  };

  // Send metric to analytics
  const sendToAnalytics = useCallback(
    async (metric: WebVitalMetric) => {
      if (!enableAnalytics) return;

      try {
        // Send to Google Analytics 4 if available
        if (typeof window !== 'undefined' && window.gtag) {
          window.gtag('event', metric.name, {
            event_category: 'Web Vitals',
            event_label: metric.id,
            value: Math.round(
              metric.name === 'CLS' ? metric.value * 1000 : metric.value
            ),
            metric_rating: metric.rating,
            metric_delta: metric.delta,
            navigation_type: metric.navigationType,
          });
        }

        // Send to custom analytics endpoint
        if (analyticsEndpoint) {
          await fetch(analyticsEndpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              metric,
              timestamp: Date.now(),
              url: window.location.href,
              userAgent: navigator.userAgent,
              connection: (
                navigator as { connection?: { effectiveType: string } }
              ).connection?.effectiveType,
            }),
          });
        }
      } catch (error) {
        // Error logging removed for production
      }
    },
    [enableAnalytics, analyticsEndpoint]
  );

  // Handle metric capture
  const handleMetric = useCallback(
    (metric: Metric) => {
      const webVitalMetric: WebVitalMetric = {
        name: metric.name,
        value: metric.value,
        rating: getPerformanceRating(metric.name, metric.value),
        delta: metric.delta,
        id: metric.id,
        navigationType: metric.navigationType || 'navigate',
      };

      // Update state
      setMetrics(prev => ({
        ...prev,
        [metric.name]: webVitalMetric,
      }));

      // Log to console if enabled and in development
      // Development logging removed for production

      // Send to analytics (only once per metric per page load)
      const metricKey = `${metric.name}-${metric.id}`;
      if (!sentMetrics.current.has(metricKey)) {
        sentMetrics.current.add(metricKey);
        sendToAnalytics(webVitalMetric);
      }

      // Call custom handler
      if (onMetricCapture) {
        onMetricCapture(webVitalMetric);
      }
    },
    [onMetricCapture, sendToAnalytics]
  );

  // Initialize Web Vitals monitoring
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // Monitor Core Web Vitals
    onCLS(handleMetric);
    onFCP(handleMetric);
    onINP(handleMetric);
    onLCP(handleMetric);
    onTTFB(handleMetric);

    // Monitor additional performance metrics
    if ('PerformanceObserver' in window) {
      // Monitor Long Tasks (for performance debugging)
      try {
        const longTaskObserver = new PerformanceObserver(list => {
          for (const entry of list.getEntries()) {
            if (entry.duration > 50) {
              // Performance logging removed for production
            }
          }
        });
        longTaskObserver.observe({ entryTypes: ['longtask'] });
      } catch (error) {
        // Long Task API not supported
      }

      // Monitor Layout Shifts for debugging
      try {
        interface LayoutShiftEntry extends PerformanceEntry {
          value: number;
          sources: Array<{ node?: Element }>;
        }

        const layoutShiftObserver = new PerformanceObserver(list => {
          for (const entry of list.getEntries()) {
            const layoutShiftEntry = entry as LayoutShiftEntry;
            if (layoutShiftEntry.value > 0.1) {
              // Performance logging removed for production
            }
          }
        });
        layoutShiftObserver.observe({ entryTypes: ['layout-shift'] });
      } catch (error) {
        // Layout Shift API not supported
      }
    }

    // Auto-hide visual indicator after 10 seconds
    if (enableVisualIndicator) {
      const timer = setTimeout(() => setIsVisible(false), 10000);
      return () => clearTimeout(timer);
    }

    // Return undefined for consistency
    return undefined;
  }, [
    enableAnalytics,
    enableConsoleLogging,
    enableVisualIndicator,
    onMetricCapture,
    analyticsEndpoint,
    handleMetric,
  ]);

  // Visual indicator component
  if (!isVisible || !enableVisualIndicator) {
    return null;
  }

  const getMetricColor = (rating: PerformanceRating) => {
    switch (rating) {
      case 'good':
        return 'text-green-600 bg-green-50';
      case 'needs-improvement':
        return 'text-yellow-600 bg-yellow-50';
      case 'poor':
        return 'text-red-600 bg-red-50';
      default:
        return 'text-gray-600 bg-gray-50';
    }
  };

  const formatValue = (name: string, value: number) => {
    if (name === 'CLS') {
      return value.toFixed(3);
    }
    return `${Math.round(value)}ms`;
  };

  return (
    <div className="fixed bottom-2 right-2 z-50 hidden max-w-xs rounded-lg border border-gray-200 bg-white p-3 shadow-lg sm:bottom-4 sm:right-4 sm:block sm:max-w-sm sm:p-4">
      <div className="mb-2 flex items-center justify-between">
        <h3 className="text-sm font-semibold text-gray-900">Core Web Vitals</h3>
        <button
          onClick={() => setIsVisible(false)}
          className="text-sm text-gray-400 hover:text-gray-600"
          aria-label="Close Web Vitals monitor"
        >
          ├ù
        </button>
      </div>

      <div className="space-y-2">
        {Object.entries(metrics).map(([name, metric]) => (
          <div key={name} className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-700">{name}</span>
            <span
              className={`rounded px-2 py-1 text-xs ${getMetricColor(metric.rating)}`}
            >
              {formatValue(name, metric.value)}
            </span>
          </div>
        ))}
      </div>

      <div className="mt-3 text-xs text-gray-500">
        <div className="flex items-center space-x-2">
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-green-500"></div>
            <span>Good</span>
          </div>
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-yellow-500"></div>
            <span>Needs Improvement</span>
          </div>
          <div className="flex items-center">
            <div className="mr-1 h-2 w-2 rounded-full bg-red-500"></div>
            <span>Poor</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// Hook for accessing Web Vitals data
export function useWebVitals() {
  const [metrics, setMetrics] = useState<CoreWebVitalsData>({});

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleMetric = (metric: Metric) => {
      const webVitalMetric: WebVitalMetric = {
        name: metric.name,
        value: metric.value,
        rating: getPerformanceRating(metric.name, metric.value),
        delta: metric.delta,
        id: metric.id,
        navigationType: metric.navigationType || 'navigate',
      };

      setMetrics(prev => ({
        ...prev,
        [metric.name]: webVitalMetric,
      }));
    };

    const getPerformanceRating = (
      name: string,
      value: number
    ): PerformanceRating => {
      const threshold = THRESHOLDS[name as keyof typeof THRESHOLDS];
      if (!threshold) return 'good';

      if (value <= threshold.good) return 'good';
      if (value <= threshold.needsImprovement) return 'needs-improvement';
      return 'poor';
    };

    onCLS(handleMetric);
    onFCP(handleMetric);
    onINP(handleMetric);
    onLCP(handleMetric);
    onTTFB(handleMetric);
  }, []);

  return metrics;
}

export default CoreWebVitalsMonitor;

