'use client';

import { useEffect } from 'react';

import { createScopedLogger } from '@/shared/utils/logger';
import { initializePerformanceOptimizations } from '@/shared/utils/performance-optimization';

const _logger = createScopedLogger('PerformanceInitializer');

/**
 * Performance Initializer Component
 *
 * Initializes performance optimizations on the client side:
 * - Preconnects to external domains
 * - Preloads critical fonts and images
 * - Sets up resource monitoring
 * - Configures performance hints
 */
export function PerformanceInitializer() {
  useEffect(() => {
    // Initialize performance optimizations
    initializePerformanceOptimizations();

    // Add critical resource hints to document head
    const addResourceHint = (
      href: string,
      rel: string,
      as?: string,
      type?: string
    ) => {
      // Check if hint already exists
      const existing = document.querySelector(
        `link[href="${href}"][rel="${rel}"]`
      );
      if (existing) return;

      const link = document.createElement('link');
      link.rel = rel;
      link.href = href;
      if (as) link.as = as;
      if (type) link.type = type;
      if (rel === 'preconnect' || rel === 'dns-prefetch') {
        link.crossOrigin = 'anonymous';
      }
      document.head.appendChild(link);
    };

    // Preconnect to critical external domains
    const criticalDomains = [
      'https://fonts.googleapis.com',
      'https://fonts.gstatic.com',
      'https://res.cloudinary.com',
      'https://images.unsplash.com',
    ];

    criticalDomains.forEach(domain => {
      addResourceHint(domain, 'preconnect');
      addResourceHint(domain, 'dns-prefetch');
    });

    // Font preloading is now handled by Next.js font optimization

    // Add viewport meta tag for mobile optimization if not present
    if (!document.querySelector('meta[name="viewport"]')) {
      const viewport = document.createElement('meta');
      viewport.name = 'viewport';
      viewport.content =
        'width=device-width, initial-scale=1, viewport-fit=cover';
      document.head.appendChild(viewport);
    }

    // Add theme-color meta tag for PWA
    if (!document.querySelector('meta[name="theme-color"]')) {
      const themeColor = document.createElement('meta');
      themeColor.name = 'theme-color';
      themeColor.content = '#8B4513'; // Coffee brown color
      document.head.appendChild(themeColor);
    }

    // Optimize scroll behavior for better performance
    if ('scrollBehavior' in document.documentElement.style) {
      document.documentElement.style.scrollBehavior = 'smooth';
    }

    // Set up intersection observer for lazy loading optimization
    if ('IntersectionObserver' in window) {
      // Enable native lazy loading for images
      const images = document.querySelectorAll('img[loading="lazy"]');
      images.forEach(img => {
        if (!img.getAttribute('loading')) {
          img.setAttribute('loading', 'lazy');
        }
      });
    }

    // Performance monitoring setup
    if ('PerformanceObserver' in window) {
      // Monitor long tasks
      try {
        const longTaskObserver = new PerformanceObserver(list => {
          list.getEntries().forEach(entry => {
            if (entry.duration > 50) {
              // Performance logging removed for production
            }
          });
        });
        longTaskObserver.observe({ entryTypes: ['longtask'] });
      } catch (e) {
        // Long task API not supported
      }

      // Monitor layout shifts
      try {
        interface LayoutShiftEntry extends PerformanceEntry {
          hadRecentInput: boolean;
          value: number;
        }

        const clsObserver = new PerformanceObserver(list => {
          list.getEntries().forEach(entry => {
            if (entry.entryType === 'layout-shift') {
              const layoutShiftEntry = entry as LayoutShiftEntry;
              if (!layoutShiftEntry.hadRecentInput) {
                // Development logging removed for production
              }
            }
          });
        });
        clsObserver.observe({ entryTypes: ['layout-shift'] });
      } catch (e) {
        // Layout shift API not supported
      }
    }

    // Service Worker registration for caching (if available)
    if ('serviceWorker' in navigator && process.env.NODE_ENV === 'production') {
      navigator.serviceWorker.register('/sw.js').catch(_error => {
        // Service Worker registration error logging removed for production
      });
    }
  }, []);

  // This component doesn't render anything
  return null;
}

'use client';

import { useEffect, useState, useCallback } from 'react';

import { createScopedLogger } from '@/shared/utils/logger';
import { measureCoreWebVitals } from '@/shared/utils/seo-monitoring';

const _logger = createScopedLogger('PerformanceMonitor');

export interface PerformanceMetrics {
  // Core Web Vitals
  lcp?: number; // Largest Contentful Paint
  fid?: number; // First Input Delay
  cls?: number; // Cumulative Layout Shift

  // Additional metrics
  fcp?: number; // First Contentful Paint
  ttfb?: number; // Time to First Byte

  // Resource metrics
  domContentLoaded?: number;
  loadComplete?: number;

  // Navigation metrics
  navigationStart?: number;
  responseStart?: number;
  domInteractive?: number;
}

export interface PerformanceRating {
  lcp: 'good' | 'needs-improvement' | 'poor' | 'unknown';
  fid: 'good' | 'needs-improvement' | 'poor' | 'unknown';
  cls: 'good' | 'needs-improvement' | 'poor' | 'unknown';
  overall: 'good' | 'needs-improvement' | 'poor' | 'unknown';
}

interface PerformanceMonitorProps {
  /** Whether to show performance metrics in development */
  showInDev?: boolean;
  /** Whether to track metrics automatically */
  autoTrack?: boolean;
  /** Callback when metrics are updated */
  onMetricsUpdate?: (
    metrics: PerformanceMetrics,
    ratings: PerformanceRating
  ) => void;
  /** Whether to show visual indicators */
  showIndicators?: boolean;
}

/**
 * Performance monitoring component that tracks Core Web Vitals and provides real-time metrics
 *
 * Features:
 * - Real-time Core Web Vitals tracking (LCP, FID, CLS)
 * - Additional performance metrics (FCP, TTFB, etc.)
 * - Performance rating system
 * - Visual indicators for development
 * - Automatic metric collection and reporting
 */
export function PerformanceMonitor({
  showInDev = false,
  autoTrack = true,
  onMetricsUpdate,
  showIndicators = false,
}: PerformanceMonitorProps) {
  const [metrics, setMetrics] = useState<PerformanceMetrics>({});
  const [ratings, setRatings] = useState<PerformanceRating>({
    lcp: 'unknown',
    fid: 'unknown',
    cls: 'unknown',
    overall: 'unknown',
  });

  // Calculate performance ratings based on Core Web Vitals thresholds
  const calculateRatings = useCallback(
    (metrics: PerformanceMetrics): PerformanceRating => {
      const lcpRating = metrics.lcp
        ? metrics.lcp <= 2500
          ? 'good'
          : metrics.lcp <= 4000
            ? 'needs-improvement'
            : 'poor'
        : 'unknown';

      const fidRating = metrics.fid
        ? metrics.fid <= 100
          ? 'good'
          : metrics.fid <= 300
            ? 'needs-improvement'
            : 'poor'
        : 'unknown';

      const clsRating =
        metrics.cls !== undefined
          ? metrics.cls <= 0.1
            ? 'good'
            : metrics.cls <= 0.25
              ? 'needs-improvement'
              : 'poor'
          : 'unknown';

      // Overall rating is the worst of the three
      const ratings = [lcpRating, fidRating, clsRating].filter(
        r => r !== 'unknown'
      );
      const overall =
        ratings.length === 0
          ? 'unknown'
          : ratings.includes('poor')
            ? 'poor'
            : ratings.includes('needs-improvement')
              ? 'needs-improvement'
              : 'good';

      return { lcp: lcpRating, fid: fidRating, cls: clsRating, overall };
    },
    []
  );

  // Collect performance metrics using Performance API
  const collectMetrics = useCallback(() => {
    if (typeof window === 'undefined' || !window.performance) return;

    const navigation = performance.getEntriesByType(
      'navigation'
    )[0] as PerformanceNavigationTiming;
    const paint = performance.getEntriesByType('paint');

    const newMetrics: PerformanceMetrics = {
      navigationStart: navigation?.startTime || 0,
      responseStart: navigation?.responseStart || 0,
      domInteractive: navigation?.domInteractive || 0,
      domContentLoaded: navigation?.domContentLoadedEventEnd || 0,
      loadComplete: navigation?.loadEventEnd || 0,
      ttfb: navigation ? navigation.responseStart - navigation.requestStart : 0,
    };

    // First Contentful Paint
    const fcpEntry = paint.find(
      entry => entry.name === 'first-contentful-paint'
    );
    if (fcpEntry) {
      newMetrics.fcp = fcpEntry.startTime;
    }

    setMetrics(prev => ({ ...prev, ...newMetrics }));
  }, []);

  // Set up Core Web Vitals observers
  useEffect(() => {
    if (!autoTrack || typeof window === 'undefined') return;

    let clsValue = 0;
    let clsEntries: PerformanceEntry[] = [];

    // Largest Contentful Paint
    const lcpObserver = new PerformanceObserver(entryList => {
      const entries = entryList.getEntries();
      const lastEntry = entries[entries.length - 1];

      if (lastEntry) {
        setMetrics(prev => ({ ...prev, lcp: lastEntry.startTime }));
      }
    });

    // First Input Delay
    interface FirstInputEntry extends PerformanceEntry {
      processingStart: number;
    }

    const fidObserver = new PerformanceObserver(entryList => {
      const entries = entryList.getEntries();
      entries.forEach(entry => {
        const fidEntry = entry as FirstInputEntry;
        const fid = fidEntry.processingStart - fidEntry.startTime;
        setMetrics(prev => ({ ...prev, fid }));
      });
    });

    // Cumulative Layout Shift
    interface LayoutShiftEntry extends PerformanceEntry {
      hadRecentInput: boolean;
      value: number;
    }

    const clsObserver = new PerformanceObserver(entryList => {
      const entries = entryList.getEntries();
      entries.forEach(entry => {
        const clsEntry = entry as LayoutShiftEntry;
        if (!clsEntry.hadRecentInput) {
          clsValue += clsEntry.value;
          clsEntries.push(clsEntry);
        }
      });

      setMetrics(prev => ({ ...prev, cls: clsValue }));
    });

    // Start observing
    try {
      lcpObserver.observe({ entryTypes: ['largest-contentful-paint'] });
      fidObserver.observe({ entryTypes: ['first-input'] });
      clsObserver.observe({ entryTypes: ['layout-shift'] });
    } catch (error) {
      // Performance Observer error logging removed for production
    }

    // Collect initial metrics
    collectMetrics();

    // Cleanup
    return () => {
      lcpObserver.disconnect();
      fidObserver.disconnect();
      clsObserver.disconnect();
    };
  }, [autoTrack, collectMetrics]);

  // Update ratings when metrics change
  useEffect(() => {
    const newRatings = calculateRatings(metrics);
    setRatings(newRatings);
    onMetricsUpdate?.(metrics, newRatings);
  }, [metrics, calculateRatings, onMetricsUpdate]);

  // Initialize Core Web Vitals monitoring from seo-monitoring.ts
  useEffect(() => {
    if (autoTrack) {
      measureCoreWebVitals();
    }
  }, [autoTrack]);

  // Don't render in production unless explicitly shown
  if (process.env.NODE_ENV === 'production' && !showIndicators) {
    return null;
  }

  // Don't render in development unless explicitly shown
  if (process.env.NODE_ENV === 'development' && !showInDev && !showIndicators) {
    return null;
  }

  if (!showIndicators) {
    return null;
  }

  const getRatingColor = (rating: string) => {
    switch (rating) {
      case 'good':
        return 'text-green-600 bg-green-100';
      case 'needs-improvement':
        return 'text-yellow-600 bg-yellow-100';
      case 'poor':
        return 'text-red-600 bg-red-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const formatMetric = (value: number | undefined, unit: string = 'ms') => {
    if (value === undefined) return 'N/A';
    return unit === 'ms' ? `${Math.round(value)}ms` : value.toFixed(3);
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 max-w-sm rounded-lg border bg-white p-4 shadow-lg">
      <h3 className="mb-2 text-sm font-semibold">Performance Metrics</h3>

      {/* Core Web Vitals */}
      <div className="space-y-2 text-xs">
        <div className="flex items-center justify-between">
          <span>LCP:</span>
          <span className={`rounded px-2 py-1 ${getRatingColor(ratings.lcp)}`}>
            {formatMetric(metrics.lcp)}
          </span>
        </div>

        <div className="flex items-center justify-between">
          <span>FID:</span>
          <span className={`rounded px-2 py-1 ${getRatingColor(ratings.fid)}`}>
            {formatMetric(metrics.fid)}
          </span>
        </div>

        <div className="flex items-center justify-between">
          <span>CLS:</span>
          <span className={`rounded px-2 py-1 ${getRatingColor(ratings.cls)}`}>
            {formatMetric(metrics.cls, '')}
          </span>
        </div>

        <hr className="my-2" />

        {/* Additional metrics */}
        <div className="flex items-center justify-between">
          <span>FCP:</span>
          <span>{formatMetric(metrics.fcp)}</span>
        </div>

        <div className="flex items-center justify-between">
          <span>TTFB:</span>
          <span>{formatMetric(metrics.ttfb)}</span>
        </div>

        <div className="flex items-center justify-between">
          <span>Load:</span>
          <span>{formatMetric(metrics.loadComplete)}</span>
        </div>

        <hr className="my-2" />

        {/* Overall rating */}
        <div className="flex items-center justify-between font-semibold">
          <span>Overall:</span>
          <span
            className={`rounded px-2 py-1 ${getRatingColor(ratings.overall)}`}
          >
            {ratings.overall.toUpperCase()}
          </span>
        </div>
      </div>
    </div>
  );
}

/**
 * Hook to access performance metrics programmatically
 */
export function usePerformanceMetrics() {
  const [metrics, setMetrics] = useState<PerformanceMetrics>({});
  const [ratings, setRatings] = useState<PerformanceRating>({
    lcp: 'unknown',
    fid: 'unknown',
    cls: 'unknown',
    overall: 'unknown',
  });

  const updateMetrics = useCallback(
    (newMetrics: PerformanceMetrics, newRatings: PerformanceRating) => {
      setMetrics(newMetrics);
      setRatings(newRatings);
    },
    []
  );

  return { metrics, ratings, updateMetrics };
}

