'use client';

import {
  Search,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Info,
  Download,
  RefreshCw,
  Globe,
  Zap,
  Eye,
  Target,
} from 'lucide-react';
import React, { useState } from 'react';

import {
  Alert,
  AlertDescription,
  AlertTitle,
} from '@/presentation/components/ui/alert';
import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import { Input } from '@/presentation/components/ui/input';
import { Progress } from '@/presentation/components/ui/progress';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/presentation/components/ui/tabs';
import { createScopedLogger } from '@/shared/utils/logger';
import { type SEOAuditResult } from '@/shared/utils/seo-audit';

const _logger = createScopedLogger('SEODashboard');

interface SEODashboardProps {
  className?: string;
  defaultUrl?: string;
  showBatchAudit?: boolean;
}

interface AuditState {
  loading: boolean;
  result: SEOAuditResult | null;
  error: string | null;
}

interface BatchAuditState {
  loading: boolean;
  results: Array<{ url: string; audit: SEOAuditResult }>;
  summary: {
    totalUrls: number;
    successful: number;
    failed: number;
    averageScore: number;
    totalIssues: number;
  } | null;
  error: string | null;
}

export function SEODashboard({
  className = '',
  defaultUrl = '',
  showBatchAudit = true,
}: SEODashboardProps) {
  const [url, setUrl] = useState(defaultUrl);
  const [batchUrls, setBatchUrls] = useState('');
  const [auditState, setAuditState] = useState<AuditState>({
    loading: false,
    result: null,
    error: null,
  });
  const [batchState, setBatchState] = useState<BatchAuditState>({
    loading: false,
    results: [],
    summary: null,
    error: null,
  });

  // Perform single URL audit
  const performAudit = async () => {
    if (!url.trim()) return;

    setAuditState({ loading: true, result: null, error: null });

    try {
      const response = await fetch('/api/seo/audit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: url.trim() }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Audit failed');
      }

      setAuditState({ loading: false, result: data.audit, error: null });
    } catch (error) {
      setAuditState({
        loading: false,
        result: null,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  };

  // Perform batch audit
  const performBatchAudit = async () => {
    const urls = batchUrls
      .split('\n')
      .map(url => url.trim())
      .filter(url => url.length > 0);

    if (urls.length === 0) return;

    setBatchState({ loading: true, results: [], summary: null, error: null });

    try {
      const response = await fetch('/api/seo/audit/batch', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ urls }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Batch audit failed');
      }

      setBatchState({
        loading: false,
        results: data.results,
        summary: data.summary,
        error: null,
      });
    } catch (error) {
      setBatchState({
        loading: false,
        results: [],
        summary: null,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  };

  // Download audit report
  const downloadReport = async () => {
    if (!url.trim()) return;

    try {
      const response = await fetch('/api/seo/audit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: url.trim(), format: 'report' }),
      });

      if (!response.ok) {
        throw new Error('Failed to generate report');
      }

      const blob = await response.blob();
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `seo-audit-${new Date().toISOString().split('T')[0]}.md`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);
    } catch (error) {
      // Download error logging removed for production
    }
  };

  // Get score color
  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  // Get issue icon
  const getIssueIcon = (type: string) => {
    switch (type) {
      case 'error':
        return <XCircle className="h-4 w-4 text-red-500" />;
      case 'warning':
        return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case 'info':
        return <Info className="h-4 w-4 text-blue-500" />;
      default:
        return <Info className="h-4 w-4 text-gray-500" />;
    }
  };

  // Get impact badge variant
  const getImpactVariant = (impact: string) => {
    switch (impact) {
      case 'high':
        return 'destructive';
      case 'medium':
        return 'default';
      case 'low':
        return 'secondary';
      default:
        return 'outline';
    }
  };

  return (
    <div className={`space-y-6 ${className}`}>
