  performance: PerformanceAudit;
  accessibility: AccessibilityAudit;
  internationalSEO: InternationalSEOAudit;
}

export interface SEOIssue {
  type: 'error' | 'warning' | 'info';
  category:
    | 'metadata'
    | 'structured-data'
    | 'performance'
    | 'accessibility'
