  private calculateScore(results: SEOTestResult[]): number {
    let score = 100;

    results.forEach(result => {
      if (!result.passed) {
        switch (result.severity) {
          case 'error':
            score -= 20;
            break;
          case 'warning':
            score -= 10;
            break;
          case 'info':
            score -= 5;
            break;
        }
      }
    });

    return Math.max(0, score);
  }

