// Generate metadata for pages
export interface SEOProps {
  title?: string;
  description?: string;
  keywords?: string[];
  image?: string;
  url?: string;
  type?: 'website' | 'article' | 'product' | 'service';
  publishedTime?: string;
  modifiedTime?: string;
  author?: string;
  section?: string;
  tags?: string[];
  locale?: Locale;
  alternateLocales?: readonly Locale[];
  noIndex?: boolean;
  canonical?: string;
}

export function generateMetadata({
  title,
  description = seoConfig.defaultDescription,
  keywords = seoConfig.defaultKeywords,
  image = seoConfig.defaultImage,
  url,
  type = 'website',
  publishedTime,
  modifiedTime,
  author,
  section,
  tags,
  locale = 'en',
  alternateLocales = locales,
  noIndex = false,
  canonical,
}: SEOProps = {}): Metadata {
  const fullTitle = title
    ? `${title} | ${seoConfig.siteName}`
    : seoConfig.defaultTitle;

  const fullUrl = url ? `${seoConfig.siteUrl}${url}` : seoConfig.siteUrl;
  const fullImage = image.startsWith('http')
    ? image
    : `${seoConfig.siteUrl}${image}`;

  const metadata: Metadata = {
    title: fullTitle,
    description,
    keywords: keywords.join(', '),
    authors: author ? [{ name: author }] : undefined,
    creator: seoConfig.siteName,
    publisher: seoConfig.siteName,
    robots: noIndex ? 'noindex, nofollow' : 'index, follow',

    // Open Graph
    openGraph: {
      type: type === 'article' ? 'article' : 'website',
      title: fullTitle,
      description,
      url: fullUrl,
      siteName: seoConfig.siteName,
      images: [
        {
          url: fullImage,
          width: 1200,
          height: 630,
          alt: title || seoConfig.defaultTitle,
        },
      ],
      locale,
      ...(type === 'article' && {
        publishedTime,
        modifiedTime,
        authors: author ? [author] : undefined,
        section,
        tags,
      }),
    },

    // Twitter
    twitter: {
      card: 'summary_large_image',
      site: seoConfig.twitterHandle,
      creator: seoConfig.twitterHandle,
      title: fullTitle,
      description,
      images: [fullImage],
    },

    // Alternate languages (hreflang)
    alternates: {
      canonical: canonical || fullUrl,
      languages: generateHreflangUrls(url, seoConfig.siteUrl, alternateLocales),
    },

    // Icons
    icons: {
      icon: seoConfig.favicon,
      apple: seoConfig.appleTouchIcon,
    },

    // Manifest
    manifest: seoConfig.manifest,

    // Additional meta tags
    other: {
      'theme-color': '#d97706', // amber-600
      'msapplication-TileColor': '#d97706',
      'apple-mobile-web-app-capable': 'yes',
      'apple-mobile-web-app-status-bar-style': 'default',
    },
  };

  return metadata;
}

